-- 0230 recuperados+crossref parte 1
INSERT OR IGNORE INTO municipios (codigo_ine,nombre,provincia,comunidad,nombre_search,es_duplicado) VALUES ('90732','Cizur','Navarra','Navarra','cizur',0);
INSERT OR IGNORE INTO municipios (codigo_ine,nombre,provincia,comunidad,nombre_search,es_duplicado) VALUES ('90733','Orkoien','Navarra','Navarra','orkoien',0);
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31905','iglesia','Iglesia de San Martín (Casco Antiguo)','Edificación barroca sencilla del siglo XVIII construida en mampostería caliza y ladrillo industrializado en posteriores reformas. Dispone de nave única abovedada con lunetos y retablo clasicista desprovisto de policromía original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33005','iglesia','Iglesia de San Nicolás de Bari','Templo de origen medieval reedificado por completo tras destrucciones bélicas coloniales en el siglo XVIII y principios del XX, conservando una monumental fachada barroca clasicista del siglo de sillería arenisca tallada. Muestra un óculo central abocinado, hornacinas integradas y una torre campanario con remate cupuliforme.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90732','monumento','Núcleos de población de Cizur','El término municipal incluye los siguientes núcleos de población: Cizur Menor, Astráin, Gazólaz, Larraya, Muru-Astráin, Paternáin, Undiano, Zariquiegui.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90732','iglesia','Iglesia de San Emeterio y San Celedonio de Gazólaz','Templo románico del siglo XIII célebre por su galería porticada. El atrio exterior consta de arcadas de medio punto apoyadas sobre capiteles dobles labrados con relieves de animales fantásticos, rostros humanos y motivos vegetales de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90732','iglesia','Iglesia de San Miguel de Cizur Menor','Antigua iglesiafortaleza de la Orden de San Juan de Jerusalén (siglo XII). Edificada en sillería compacta, presenta un ábside semicircular, ménsulas historiadas en el alero y una torre albarrana adosada con aspilleras defensivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90732','iglesia','Iglesia de San Andrés de Zariquiegui','Templo románico que destaca por su portada abocinada con capiteles historiados y un tímpano que alberga un crismón trinitario tallado en bajorrelieve con técnica de aristas vivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31090','iglesia','Iglesia de San Miguel','Construcción de carácter rural montañés en mampostería caliza y tejado a dos aguas con teja arcillosa. Interior simple con vigas de madera de castaño vistas y un retablo barroco popular de madera policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31091','iglesia','Iglesia de San Pedro de Unanu','Templo medieval edificado en sillería basta y esquinales regularizados. Cuenta con un arco fajón apuntado que soporta una cubierta de madera a dos aguas y una pila bautismal de piedra caliza del siglo XIII con motivos geométricos incisos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45065','iglesia','Iglesia de San Pedro de la Rúa','Conjunto románico del siglo XII edificado en sillería arenisca de perfecta labra. Destaca su imponente portada con arcos polilobulados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45065','palacio','Palacio de los Reyes de Navarra','Único ejemplo de arquitectura civil románica en la comunidad (siglo XII). Fachada de dos cuerpos en sillería regular con amplios ventanales geminados divididos por columnillas y un famoso capitel que representa el combate de Roldán contra el gigante Ferragut.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45065','iglesia','Iglesia de San Miguel','Templo románico tardío dotado de una portada septentrional de rango internacional, provista de un tímpano con el Pantocrátor y el Tetramorfos, flanqueada por altorrelieves esculpidos con exquisito detalle que representan las Tres Marías ante el sepulcro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31099','iglesia','Iglesia de Nuestra Señora de la Asunción','Obra del siglo XVI realizada en mampostería caliza y esquinales de cantería regular. Alberga una nave de planta rectangular dividida por arcos de medio punto y coro alto rústico de vigas de madera machihembradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31103','monumento','Núcleos de población de Ezprogui','El término municipal incluye los siguientes núcleos de población: Guetádar y Moriones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31103','iglesia','Iglesia de San Juan Bautista de Moriones','Fábrica del siglo XVI de carácter rural levantada en mampostería basta y sillería en los ángulos. Interior simple con bóveda de cañón rebajada sobre fajones cuadrados y retablo mayor barroco popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31111','iglesia','Iglesia de San Eulogio','Templo rural medieval construido en sillería regular y sillarejo calizo. Presenta una planta de nave única rectangular con bóveda de cañón apuntada reforzada por arcos fajones simples sobre pilastras planas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31112','iglesia','Iglesia de San Andrés','Fábrica del siglo XVI de arquitectura pirenaica en sillería arenisca. Interior cubierto por bóveda de crucería estrellada con terceletes y claves talladas. El coro alto muestra vigas soleras de madera de roble labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31113','iglesia','Iglesia de Santiago','Edificio gótico del siglo XVI levantado en sillería arenisca compacta. Posee una nave única rectangular con cabecera poligonal y cubiertas resueltas mediante bóveda de crucería estrellada con nervios moldurados sobre ménsulas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31139','monumento','Núcleos de población de Lana','El término municipal incluye los siguientes núcleos de población: Galbarra, Gastiáin, Narcué, Ulíbarri y Viloria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31139','iglesia','Iglesia de San Pedro de Galbarra','Templo del siglo XVI edificado en piedra de sillería caliza. Alberga una planta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31139','ermita','Ermita de Santa María de la Antigua de Narcué','Edificio románico del siglo XII construido en mampostería basta. Conserva un ábside semicircular con canes geométricos en el alero y una Portada abocinada con dos arquivoltas lisas apoyadas sobre jambas rectas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31160','iglesia','Iglesia de San Martín de Tours','Fábrica barroca del siglo XVIII edificada sobre restos medievales combinando sillería en los puntos de articulación y mampostería en los paramentos. Posee un crucero monumental cubierto por cúpula sobre pechinas caladas con yeserías decorativas barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31160','iglesia','Basílica de la Virgen del Milagro','Ermita del siglo XVII de traza clasicista construida en piedra de cantería regular con planta de cruz latina y cúpula de media naranja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31177','iglesia','Iglesia de San Esteban','Templo de origen gótico (siglo XIV) modificado sustancialmente en la etapa barroca, edificado en fábrica de mampostería regular con esquinales de sillería arenisca. Su interior consta de una nave única articulada con arcos fajones rebajados que sostienen bóvedas de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31177','monumento','Caserón de los Echávarri','Palacio de Cabo de Armería del siglo XVII ejecutado en cantería caliza. Presenta una fachada simétrica con un portalón central de medio punto dovelado y un gran blasón barroco labrado con volutas y timbrado por celada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31187','iglesia','Iglesia de San Tiburcio','Edificio de carácter rural del siglo Baltasar (siglo XVII) levantado en aparejo rústico de caliza local. Consta de una nave única rectangular con cabecera plana y cubierta de madera de pino silvestre','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31188','monumento','Núcleos de población de Olaibar','El término municipal incluye los siguientes núcleos de población: Endériz, Olaiz, Olave, Osacáin y Enderiz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31188','iglesia','Iglesia de San Nicolás de Bari de Endériz','Fábrica de transición gótica ejecutada en sillería regular y mampostería. Alberga una bóveda de crucería simple con nervios diagonales moldurados y claves lisas, además de una portada meridional apuntada de tres arquivoltas lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31188','palacio','Palacio de Cabo de Armería de Olave','Estructura señorial del siglo XVI construida en bloque cúbico de cantería caliza. Conserva saeteras defensivas en su base y un portalón central de medio punto con dovelas radiales de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31189','iglesia','Iglesia de San Miguel','Templo monumental góticorenacentista del siglo XVI construido en sillería caliza regular. Su única nave está rematada por un ábside poligonal cubierto con una intrincada bóveda de crucería estrellada con terceletes y ligaduras de fina labra geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31189','ermita','Ermita de Nuestra Señora de Belén','Construcción rural bajomedieval en mampostería caliza y contrafuertes de sillería escuadrada, que custodia en su interior un coro alto de madera de roble machihembrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31190','iglesia','Iglesia de Santiago','Edificio del siglo XVI levantado en cantería regular de arenisca compacta. Cuenta con una nave única de tres tramos que culmina en una cabecera poligonal cubierta por una bóveda de crucería estrellada con claves talladas con motivos hagiográficos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31190','monumento','Dar prioridad en el próximo bloque a Olite por su conjunto monumental internacional','Dar prioridad en el próximo bloque a Olite por su conjunto monumental internacional','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','palacio','Palacio Real de Olite','Alcázar gótico de rango internacional (siglos XIV y XV) mandado erigir por Carlos III el Noble, construido en sillería caliza y arenisca de perfecta labra. Presenta un diseño de torres exentas almenadas (Torre del Homenaje, Torre de las Tres','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','iglesia','Iglesia de Santa María la Real','Templo gótico del siglo XIV adosado al palacio. Destaca su fachada monumental con una gran portada abocinada de ocho arquivoltas profusamente esculpidas, un tímpano calado con la representación hagiográfica de la Virgen y un rosetón central calado de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','iglesia','Iglesia de San Pedro','Templo medieval que combina un ábside y portada de traza románica tardía (siglo XII) con una esbelta torre gótica de aguja (siglo XIV) de planta octogonal. La portada presenta un arco apuntado con arquivoltas labradas y un tímpano decorado con relieves de perfecta labra iconográfica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31195','monumento','Fábrica de Armas de Orbaitzeta','Complejo de arqueología industrial del siglo XVIII edificado en mampostería caliza basta y arquerías de sillería. Conserva las canalizaciones hidráulicas del río Legarza subterráneas hechas con opus caementicium, los hornos de fundición abovedados y las viviendas obreras organizadas en torno a un gran patio central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31195','iglesia','Iglesia de San Pedro','Templo rural de origen gótico (siglo XVI) construido en piedra caliza compacta. Presenta una única nave rectangular rematada por cabecera plana con artesonado de madera de roble machihembrada con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31196','iglesia','Iglesia de San Juan Evangelista','Fábrica gótica de transición (siglo XVI) levantada en aparejo rústico de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31196','monumento','Dar prioridad a los municipios con patrimonio de la arquitectura industrial','Dar prioridad a los municipios con patrimonio de la arquitectura industrial','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31197','iglesia','Iglesia de San Martín','Templo románico de mediados del siglo XII construido en sillería regular arenisca. Destaca su ábside semicircular con canecillos historiados de fina labra y, especialmente, su cripta subterránea, un espacio absidial cubierto con bóveda de horno apuntalada por seis robustas columnas con capiteles de temática vegetal abstracta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31197','ermita','Ermita de San Pelayo','Construcción rural de origen medieval en mampostería basta y esquinales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90733','iglesia','Iglesia de San Miguel','Fábrica de origen gótico (siglo XIV) con importantes remodelaciones en la etapa barroca, levantada en sillería caliza compacta y mampostería enlucida. Su nave única rectangular se cubre mediante una bóveda de cañón con lunetos y alberga una pila bautismal monolítica medieval labrada a bisel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31198','iglesia','Iglesia de la Asunción','Edificio de carácter gótico rural del siglo XVI construido en aparejo rústico de caliza gris y esquinales de cantería regular. Su planta se unifica en una nave única que remata en testero plano, cubierta por una bóveda de crucería simple con arcos fajones de sección cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31199','iglesia','Iglesia de San Adrián','Templo gótico-renacentista del siglo XVI ejecutado en sillería regular caliza. El espacio interior se organiza en una nave única con cabecera poligonal techada mediante bóvedas de crucería estrellada con terceletes y claves talladas con motivos hagiográficos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31199','monumento','Restos de la Antigua Real Fábrica de Fundición','Vestigios de arqueología industrial del siglo XVIII construidos en mampostería basta, de los que subsisten los cárcavos de captación hidráulica y los arranques de arquerías rebajadas de ladrillo macizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31200','iglesia','Iglesia de San Miguel','Templo monumental iniciado en el siglo XIV en estilo gótico y ampliado en los siglos XVI y XVIII, edificado en sillería arenisca regular. Presenta una planta de cruz latina con un crucero techado por una bóveda de crucería estrellada con ligaduras de gran virtuosismo escultórico y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31200','ermita','Ermita de San Salvador','Santuario medieval fortificado erigido sobre un cerro perimetral, construido en cantería y mampostería con una robusta torre adosada dotada de saeteras medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31200','monumento','Continuar con el orden alfabético estricto establecido','Continuar con el orden alfabético estricto establecido','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31201','catedral','Catedral de Santa María la Real','Complejo catedralicio gótico de los siglos XIV y XV (con fachada neoclásica de Ventura Rodríguez), erigido en perfecta sillería caliza calada. Destaca su claustro gótico de rango internacional, integrado por arquerías ojivales de fina tracería calada con maineles sutiles, capiteles historiados de extraordinario virtuosismo escultórico y el suntuoso sepulcro de alabastro de Carlos III de Navarra de perfecta labra anatómica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31201','monumento','Ciudadela y Recinto Amurallado','Fortificación renacentista de traza italiana (siglos XVI y XVII) diseñada por Giacomo Palearo, ejecutada en sillería regular y gruesos taludes de mampostería pesada. Presenta una planta pentagonal estrellada de cinco baluartes balizados, dotada de casamatas, revellines, fosos perimetrales y puentes levadizos con portadas barrocas almohadilladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31201','iglesia','Iglesia de San Cernin (San Saturnino)','** Templofortaleza del gótico temprano (siglo XIII) construido en sillería regular. Presenta dos imponentes torres defensivas cuadrangulares de aspecto militar coronadas por almenas, una amplísima nave única y una gran portada abocinada de seis arquivoltas profusamente decorada con motivos hagiográficos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31201','monumento','Casa Consistorial','Edificio civil barroco del siglo XVIII (fachada clasicista de José de Zay y Lorda), tallado en piedra arenisca de fina cantería. Cuenta con una fachada organizada en tres cuerpos superpuestos de órdenes','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31202','iglesia','Iglesia de San Juan Evangelista','Templo monumental iniciado en el siglo XVI en estilo renacentista y ampliado en la etapa neoclásica (siglo XVIII), construido en perfecta sillería caliza compacta. Alberga una planta basilical de grandes proporciones coronada por cúpula sobre pechinas con yeserías ornamentales y un suntuoso retablo mayor manierista de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31202','monumento','La Atalaya y Restos del Castillo','Ruinas de una fortaleza medieval (siglo XII) situadas sobre un escarpe rocoso. Subsiste la base de una torre vigía semicircular de mampostería basta y lienzos de muralla ejecutados en tapial reforzado con cal y guijarros de río.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31203','iglesia','Iglesia de San Millán','Iglesia-fortaleza de origen gótico (siglo XIV) tallada en sillería regular caliza. Posee un carácter marcadamente militar con muros ciegos de gran espesor, una portada apuntada abocinada de tres arquivoltas lisas y una nave única cubierta por bóvedas de crucería simple con arcos torales rectangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31203','monumento','Casa Natal de Santiago Ramón y Cajal','Vivienda tradicional de arquitectura civil aragonesa (siglo XVIII) edificada en aparejo de mampostería regular con esquinales de piedra labrada. Conserva su portalón adintelado de madera de roble maciza y un alero de ladrillo moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31204','iglesia','Iglesia de Santa María','Fábrica monumental góticorenacentista del siglo XVI levantada en cantería regular de arenisca compacta. Cuenta con una nave rectangular que remata en un ábside poligonal, cubierto por una bóveda de crucería estrellada con terceletes y un retablo mayor manierista de perfecta labra anatómica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31205','iglesia','Iglesia de San Pedro','Edificio del siglo XVI de transición renacentista edificado en piedra caliza regular. Su única nave está rematada por un ábside pentagonal cubierto con una intrincada bóveda de crucería estrellada con terceletes y ligaduras de fina labra geométrica, complementada por una torre campanario barroca de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','monumento','Puente Románico sobre el Río Arga','Infraestructura viaria del siglo XI de rango internacional, hito del Camino de Santiago, levantada en sillería caliza calada de perfecta labra. Presenta seis arcos de medio punto decrecientes y perfiles alomados, provisto de tajamares triangulares perforados por arquillos de alivio para disminuir la presión hidráulica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','iglesia','Iglesia de Santiago el Mayor','Templo gótico del siglo XIV edificado sobre una fábrica románica previa. Destaca su portalón meridional de influencia mozárabe, que exhibe un arco polilobulado abocinado con cinco arquivoltas profusamente decoradas con relieves hagiográficos, y un interior que custodia la célebre talla gótica de madera policromada de Santiago Peregrino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','iglesia','Iglesia del Crucifijo','Templo gótico de los siglos XII y XIV construido por los caballeros templarios en piedra de sillería arenisca. Consta de dos naves paralelas abovedadas y alberga un crucifijo gótico de origen renano tallado en madera en forma de "Y", obra cumbre de la imaginería bajomedieval europea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31207','iglesia','Iglesia de la Asunción','Edificio monumental del siglo XVI ejecutado en sillería caliza compacta y mampostería regular. Consta de una nave única articulada con potentes arcos fajones apuntados que sostienen bóvedas de crucería estrellada con terceletes y claves talladas con motivos hagiográficos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31207','ermita','Ermita de Santiago','Santuario gótico de carácter rural edificado en un cerro exento mediante muros de mampostería basta y contrafuertes de cantería regular, que alberga una portada de arco apuntado de dovelas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31208','iglesia','Iglesia de San Blas','Templo de origen gótico-mudéjar (siglo XIV) profundamente reformado en las etapas barroca y neoclásica, construido en ladrillo visto sobre un zócalo perimetral de piedra de sillería caliza. Su única nave aloja capillas hornacinas laterales y se cubre con bóvedas de arista revocadas en yesería lisa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31209','iglesia','Iglesia de la Purificación de Arboniés','Joya del románico rural de finales del siglo XII levantada en cantería regular arenisca. Presenta un ábside semicircular con canes moldurados en el alero y una portada meridional abocinada de tres arquivoltas que apean sobre capiteles esculpidos con motivos zoomorfos y geométricos de gran virtuosismo popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31209','monumento','Foz de Arbayún (Infraestructuras históricas)','Puentes medievales y canalizaciones talladas directamente en la roca caliza de los escarpes para la conducción del agua del río Salazar, ejecutados en mampostería rústica trabada con mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31210','iglesia','Iglesia de San Esteban','Templo fortificado góticorenacentista del siglo XVI levantado en perfecta sillería caliza gris. Posee una nave de grandes proporciones coronada por bóvedas de crucería estrellada con ligaduras de fina labra geométrica, y un suntuoso retablo mayor barroco churrigueresco de madera tallada y dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31210','monumento','Mausoleo de Julián Gayarre','Conjunto escultórico exento en el cementerio municipal, obra cumbre de Mariano Benlliure de finales del siglo XIX realizada en bronce fundido y mármol de Carrara de rango internacional, con alegorías de la Armonía y la Melodía talladas con extraordinario virtuosismo anatómico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31212','iglesia','Iglesia de San Vicente','Templo de origen gótico (siglo XIV) modificado en el siglo XVI, edificado en sillería caliza compacta. Alberga una nave única dividida por arcos torales apuntados, techada con una bóveda de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31212','ermita','Ermita de la Virgen del Cortijo','Construcción románica de finales del siglo XII realizada en mampostería basta y esquinales escuadrados. Presenta una portada sencilla de arco de medio punto con dovelas regulares y un ábside semicircular con canecillos lisos en el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31213','iglesia','Iglesia de San Juan Bautista','Templo rural de origen medieval reformado en el siglo XVIII, levantado en aparejo rústico de caliza local. Dispone de una nave rectangular cubierta por bóvedas de arista revocadas en yesería lisa y una robusta torre campanario de planta cuadrada con vanos de medio punto para los bronces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31215','iglesia','Iglesia de la Santísima Trinidad','Fábrica monumental iniciada en el siglo XVI en estilo renacentista y ampliada en el siglo XX, construida en ladrillo visto sobre un zócalo perimetral de sillería arenisca. Su interior consta de una amplia nave basilical con capillas laterales hornacinas, cubierta por una bóveda de cañón con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31215','ermita','Ermita del Calvario','Construcción barroca del siglo XVII ejecutada en ladrillo visto moldurado. Presenta una planta de cruz latina con un crucero cubierto por una cúpula de media naranja sobre pechinas caladas, decoradas con yeserías de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31217','iglesia','Iglesia de San Martín de Tours','Joya del románico de mediados del siglo XII tallada en sillería regular arenisca. Destaca su ábside semicircular con columnas adosadas y capiteles historiados de perfecta labra, y sobre todo su cripta subterránea románica, espacio absidial abovedado apuntalado por seis columnas monolíticas con capiteles esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31217','ermita','Ermita de San Miguel','Templo protogótico del siglo XIII construido en cantería regular. Posee un carácter marcadamente militar con muros ciegos de gran espesor y una portada apuntada abocinada de tres arquivoltas molduradas que apean sobre capiteles de temática vegetal abstracta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31216','iglesia','Iglesia de Santa María la Real','Templo monumental románico-gótico de los siglos XII y XIV de rango internacional, erigido en perfecta sillería caliza calada. Destaca su fachada románica, una obra cumbre de la escultura medieval europea con un doble apostolado y un tímpano que representa el Juicio Final con extraordinario virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31216','palacio','Palacio de los Reyes de Navarra (Castillo de Sangüesa)','** Residencia fortificada gótica del siglo XIII construida en cantería de sillería regular y mampostería pesada. Presenta una planta rectangular con torres angulares almenadas, adarves perimetrales y muros provistos de troneras y saeteras medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31216','iglesia','Convento de San Francisco','Complejo monástico gótico del siglo XIII fundado por San Francisco de Asís. Conserva un claustro monumental integrado por','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31216','monumento','Dar prioridad a los municipios de la Zona Media con conjuntos amurallados','Dar prioridad a los municipios de la Zona Media con conjuntos amurallados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31219','iglesia','Iglesia de San Zoilo','Templo de factura barroca del siglo XVIII ejecutado en sillería regular y mampostería enlucida. Su planta se articula en una nave única cubierta por una bóveda de cañón con lunetos sobre pilastras toscanas, albergando un retablo mayor churrigueresco tallado en madera policromada de fina cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31219','monumento','Casas Señoriales del Núcleo Urbano','Palacetes barrocos barrocos de los siglos XVII y XVIII con fachadas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31220','monumento','Castillo de Santacara','Ruinas de una fortaleza medieval del siglo XIII levantada en sillería caliza compacta. Subsiste un imponente lienzo de la torre del homenaje, una estructura colosal partida verticalmente que muestra saeteras primitivas y arranques de bóvedas interiores de arco apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31220','monumento','Ciudad Romana de Cara','Yacimiento arqueológico con estructuras consolidadas en opus quadratum y opus caementicium de los siglos I a. C. al IV d. C. Conserva tramos de la muralla perimetral, cimentaciones de viviendas absidiales y vestigios de un cardo máximo pavimentado con losas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31222','iglesia','Iglesia de San Martín de Sarriés','Fábrica gótica rural del siglo XVI levantada en aparejo rústico de caliza y esquinales escuadrados. Consta de una nave única rectangular con cabecera de testero plano cubierta por bóveda de crucería simple con arcos torales rectangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31222','iglesia','Iglesia de la Asunción de Ibilcieta','Templo medieval reformado que custodia una portada apuntada abocinada de arcos lisos concéntricos y un coro alto de madera de roble machihembrada con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31223','iglesia','Iglesia de la Virgen del Rosario','Edificio de construcción contemporánea edificado tras las destrucciones bélicas de la zona, combinando sillería caliza en los pilares de articulación y paños de ladrillo visto. Conserva una pila bautismal monolítica del siglo XVI labrada a bisel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31224','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo monumental iniciado en el siglo XVI en estilo góticorenacentista y completado en el período barroco, edificado en sillería caliza compacta y ladrillo macizo. Destaca su suntuoso interior de nave única abovedada con crucerías estrelladas y un monumental órgano barroco del siglo XVIII dotado de una caja de madera de nogal tallada con gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31224','monumento','Ayuntamiento y Casas Señoriales','Conjunto de arquitectura civil barroca barroca ejecutado en ladrillo visto sobre zócalo de sillería arenisca, caracterizado por galerías de arquerías dobladas de medio punto en los áticos y blasones heráldicos de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31225','iglesia','Basílica de San Gregorio Ostiense','Obra cumbre del barroco navarro del siglo XVIII de rango nacional, emplazada sobre un cerro y ejecutada en sillería caliza de perfecta labra. Presenta una fachada-retablo monumental abocinada de arcos mixtilíneos con una profusa decoración de esculturas y relieves de extraordinario virtuosismo; el interior muestra una planta de cruz latina coronada por una cúpula sobre pechinas ornamentada con yeserías caladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31226','monumento','Puente Medieval de Sunbilla','Infraestructura viaria sobre el río Bidasoa (siglo XVI) construida en sillería regular y mampostería caliza gris. Consta de tres arcos rebajados bien escuadrados apoyados sobre robustos tajamares triangulares diseñados para resistir las avenidas fluviales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31226','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVIII levantado en aparejo de sillería regular en los vanos y sillarejo en los paramentos. Alberga una nave de traza clasicista con bóvedas de arista y una torre campanario cuadrangular que remata en un cuerpo octogonal con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31227','iglesia','Iglesia de Santa María','Templo gótico-renacentista del siglo XVI construido en sillería caliza calada de gran magnitud. Custodia el retablo mayor de Santa María, obra maestra de rango nacional esculpida por Juan de Anchieta, caracterizada por relieves anatómicos manieristas de asombroso virtuosismo escultórico y perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31227','palacio','Palacio de los Mariscales de Navarra (Palacio de los Mencos)','** Residencia palaciega fortificada del siglo XVI conectada a los restos de la muralla urbana. Presenta fábrica de sillería de cantería regular, fachada simétrica adintelada con un gran blasón central y una torre de flanqueo cuadrangular con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31227','iglesia','Iglesia de Santiago','Edificio monumental románicogótico de los siglos XII y XIII ejecutado en cantería arenisca. Muestra una portada abocinada apuntada con arquivoltas molduradas e impostas ajedrezadas, y un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31228','monumento','Núcleos de población de Tiebas-Muruarte de Reta','El término municipal incluye los siguientes núcleos de población: Tiebas y Muruarte de Reta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31228','palacio','Castillo-Palacio de Tiebas','Ruinas consolidadas de una fortaleza gótica del siglo XIII mandada erigir por Teobaldo II, construida en sillería caliza regular. Conserva la planta rectangular reforzada por torres angulares de sección cuadrada, lienzos de muralla provistos de aspilleras medievales y pavimentos originales de baldosas cerámicas polícromas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31228','iglesia','Iglesia de Santa Eufemia de Tiebas','Templo gótico puro del siglo XIV edificado en cantería. Posee una nave única rectangular que remata en una cabecera absidial poligonal, techada mediante una bóveda de crucería simple con nervios diagonales moldurados y claves ornamentadas con relieves heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31229','iglesia','Iglesia de la Inmaculada Concepción','Templo de factura neoclásica del siglo XVIII erigido sobre cimientos góticos, empleando fábrica de mampostería caliza y esquinales de sillería escuadrada. Su nave única se cubre mediante una bóveda de cañón con lunetos y posee una pila bautismal monolítica medieval de sección circular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31230','monumento','Núcleos de población de Torralba del Río','El término municipal incluye los siguientes núcleos de población: Otiñano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31230','iglesia','Iglesia de Santa María','Templo fortificado de origen gótico (siglo XIV) modificado en el siglo XVI, edificado en sillería arenisca compacta. Presenta una cabecera poligonal cubierta por una bóveda de crucería estrellada con terceletes y una torre campanario robusta integrada en el recinto amurallado de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31230','monumento','Recinto Amurallado de la Villa','Conjunto defensivo medieval del que subsisten lienzos de mampostería pesada y dos torres de flanqueo cuadrangulares, además del Portal de San Juan, con arco apuntado dovelado de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31231','iglesia','Iglesia del Santo Sepulcro','Joya del románico pleno del siglo XII vinculada a la orden del Santo Sepulcro y al Camino de Santiago, tallada en sillería caliza con planta octogonal perfecta. El interior destaca por una cúpula de nervios cruzados exentos de influencia califal cordobesa de rango internacional, y capiteles historiados de extraordinario virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31231','iglesia','Iglesia Parroquial de San Andrés','Fábrica góticorenacentista del siglo XVI levantada en sillería regular. Cuenta con una amplia nave rectangular coronada por bóvedas de crucería de diseño geométrico moldurado y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31233','iglesia','Monasterio de Santa María de la Caridad','Primer cenobio cisterciense femenino de España (siglo XII), edificado en perfecta sillería caliza compacta y ladrillo. La iglesia monástica presenta un ábside semicircular románico abovedado en horno, una portada apuntada de tres arquivoltas lisas y alberga una valiosa colección de tablas góticas y capiteles foliáceos de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31234','iglesia','Iglesia de la Asunción','Edificio monumental del siglo XVI ejecutado en sillería regular y mampostería enlucida. Su nave única se divide en tres tramos mediante arcos torales apuntados que sostienen bóvedas de crucería simple con claves talladas con motivos hagiográficos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','catedral','Catedral de Santa María','Templo gótico de transición (siglo XII al XIII) erigido sobre la antigua mezquita mayor, tallado en sillería caliza compacta. Destaca su monumental Puerta del Juicio, un acceso abocinado de ocho arquivoltas apuntadas con relieves que muestran el Juicio Final con extraordinario virtuosismo escultórico, y un claustro románico exento con capiteles historiados de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','palacio','Palacio del Marqués de San Adrián','Palacio renacentista del siglo XVI ejecutado en ladrillo visto sobre base de sillería. Sobresale su alero monumental de madera de roble tallada con modillones antropomorfos de gran minuciosidad y un patio interior porticado con columnas toscanas y casetones de estuco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','monumento','Puente del Ebro','Infraestructura viaria de origen medieval con diecisiete ojos de fábrica mixta de sillería caliza y mampostería regular. Presenta arcos de medio punto y apuntados provistos de potentes tajamares triangulares aguas arriba para la contención de avenidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31235','iglesia','Iglesia-Fortaleza de Santa María de Ujué','Santuario fortificado románico-gótico (siglos XII al XIV) edificado en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31235','monumento','Castillazo y Restos de la Muralla','Ruinas consolidadas del complejo defensivo medieval real, con cimientos en opus quadratum, aljibes subterráneos excavados en roca y lienzos de mampostería pesada con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31236','iglesia','Iglesia de San Pedro de Larrainzar','Templo de origen gótico rural modificado en la etapa barroca, levantado en aparejo rústico de caliza gris. Presenta cabecera plana, una torre campanario robusta a los pies y una bóveda de crucería simple con nervios de sección cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31236','monumento','Caseríos de Auza y Elzaburu','Conjunto de arquitectura tradicional norteña (siglos XVII y XVIII). Estructuras exentas con plantas bajas de mampostería basta para el ganado y pisos superiores entramados de madera de roble, portones de medio punto dovelados y amplios aleros de madera machihembrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31237','monumento','Núcleos de población de Unciti','El término municipal incluye los siguientes núcleos de población: Alzórriz, Artáiz, Cemboráin, Najurieta, Unciti y Zabalceta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31237','iglesia','Iglesia de San Martín de Artáiz','Obra cumbre del románico rural de finales del siglo XII tallada en sillería regular arenisca. Destaca su portada meridional','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31237','palacio','Palacio de Cabo de Armería de Alzórriz','Torre-palacio señorial fortificada del siglo XVI realizada en bloque cúbico de piedra caliza con saeteras en la base y un portalón rebajado con dovelas radiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31249','iglesia','Iglesia de Santa María','Templo monumental del siglo XVI de transición gótico-renacentista, edificado en sillería caliza y ladrillo visto. Su interior destaca por una anchísima nave única con capillas hornacinas entre los contrafuertes, cubierta por bóvedas de crucería estrellada con terceletes y un imponente retablo mayor manierista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31249','monumento','Casas Cueva de Valtierra','Conjunto de arquitectura popular excavado en los frentes de los taludes de yesos y margas de la ribera del Ebro. Presentan chimeneas exteriores troncocónicas encaladas y fachadas rústicas integradas en la roca con dinteles de madera de pino silvestre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','iglesia','Iglesia de Santa María','Templo monumental gótico de los siglos XIV al XVI erigido en sillería caliza compacta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','iglesia','Ruinas de la Iglesia de San Pedro','Restos monumentales de un templo gótico del siglo XIII construido en cantería. Se conserva el imponente ábside poligonal con ventanales apuntados de fina tracería calada y una portada barroca del siglo XVIII con columnas corintias y hornacinas exentas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31251','monumento','Recinto Amurallado y Portales Históricos','Lienzos de muralla medieval en mampostería pesada reforzada con torres cuadrangulares, de los que subsisten accesos como el Portal de San Felices con un arco apuntado dovelado de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31252','iglesia','Iglesia de San Pedro','Templo gótico rural del siglo XVI levantado en aparejo rústico de piedra caliza grisácea. Presenta una planta de nave única que remata en testero plano, techada mediante una bóveda de crucería simple cuyos nervios apean sobre ménsulas cilíndricas empotradas en los muros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31254','iglesia','Iglesia de Santa Eufemia','Fábrica barroca monumental del siglo XVIII edificada en ladrillo visto sobre un zócalo perimetral de sillería caliza. Su interior presenta planta de cruz latina con un amplio crucero coronado por una gran','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31254','palacio','Palacio de Bobadilla','Residencia palaciega barroca del siglo XVIII ejecutada en ladrillo visto moldurado. Exhibe una fachada simétrica con una arquería superior de arcos rebajados de estilo aragonés, balconajes de forja artística y blasones de cantería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31255','monumento','Castillo de San Esteban de Deyo','Fortaleza medieval de origen islámico (siglo X) emplazada sobre la cumbre de un cerro rocoso, construida en mampostería basta y sillería en los puntos de articulación. Conserva sus murallas perimetrales almenadas, un aljibe abovedado subterráneo excavado en la roca y la base de la torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31255','iglesia','Iglesia de San Andrés','Templo románico de finales del siglo XII labrado en sillería arenisca. Posee un ábside semicircular con canes moldurados en el alero, una magnífica portada abocinada de arcos apuntados de transición y una torre campanario barroca de ladrillo visto añadida en el siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31257','iglesia','Iglesia de la Asunción','Edificio de origen románico profundamente reformado en estilo gótico en el siglo XIV, ejecutado en sillería regular. Presenta una planta rectangular con cabecera poligonal y bóvedas de crucería simple con claves talladas, además de una torre campanario robusta fortificada con saeteras medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31257','monumento','Puente Medieval sobre el Río Iranzu','Infraestructura viaria vinculada al Camino de Santiago construida en sólida cantería caliza. Consta de dos arcos de medio punto bien escuadrados apoyados sobre un tajamar triangular central diseñado para la contención hidráulica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31258','iglesia','Iglesia de San Andrés','Fábrica neogótica de principios del siglo XX construida sobre cimientos bajomedievales, combinando sillería caliza compacta en los nervios y contrafuertes con paramentos de cantería regular. Conserva de la estructura antigua una cripta subterránea abovedada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31258','ermita','Ermita de la Trinidad de Arre','Complejo medieval fortificado del siglo XII que ejerce de hospital de peregrinos en el Camino de Santiago. Presenta muros de gruesa mampostería, un puente románico de seis ojos sobre el río Ulzama de perfecta labra y un ábside semicircular integrado en el núcleo residencial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31261','iglesia','Monasterio de San Salvador de Leyre','Conjunto monástico benedictino de los siglos XI y XII de relevancia internacional, tallado en sillería regular caliza. Destaca su cripta románica primitiva, un espacio subterráneo con una densa selva de columnas exentas de capiteles toscos y arcos de medio punto peraltados de gran robustez. La iglesia abacial ostenta una imponente portada románica, la "Porta Speciosa", con arquivoltas profusamente esculpidas de extraordinario virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31261','monumento','Puente de los Roncaleses','Ruinas monumentales de una infraestructura viaria medieval (siglo XI) levantada sobre el río Aragón en mampostería pesada y dovelas de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31262','iglesia','Iglesia de la Asunción de Arraiza','Templo góticorenacentista del siglo XVI construido en fábrica de mampostería basta con esquinales de sillería. Su interior alberga una nave única rectangular con cabecera de testero plano techada mediante una bóveda de crucería simple con arcos torales rectangulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31262','palacio','Palacio señorial de Arraiza','Casona barroca del siglo XVII ejecutada en sillería arenisca, con un portalón central adintelado flanqueado por columnas toscanas y un blasón de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31907','iglesia','Iglesia de San Andrés Apóstol','Fábrica gótica del siglo XIV erigida en sillería caliza compacta. Alberga una nave única dividida por arcos torales apuntados que sostienen bóvedas de crucería simple con claves labradas con motivos hagiográficos, y un suntuoso retablo mayor renacentista plateresco del siglo XVI de perfecta labra anatómica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','monumento','Universidad Laboral de Gijón','Colosal complejo arquitectónico de rango internacional edificado a mediados del siglo XX por Luis Moya, construido en sillería de granito, arenisca compacta y ladrillo macizo. Destaca su monumental patio central porticado, una iglesia de planta elíptica cubierta por una cúpula tabicada de ladrillo visto de extraordinario virtuosismo escultórico, y una torre campanario inspirada en la Giralda con más de cien metros de altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','palacio','Palacio de Revillagigedo','Obra cumbre del barroco asturiano del siglo XVIII que integra una torre bajomedieval previa del siglo XV, levantada en sillería caliza de perfecta labra. Presenta una fachada monumental organizada en cinco cuerpos con dos torres angulares almenadas, portón barroco de medio punto almohadillado y blasones de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','monumento','Termas Romanas de Campo Valdés','Complejo musealizado de baños públicos del siglo II d. C. ejecutado en opus quadratum, opus caementicium y opus latericium. Conserva las estructuras perimetrales del caldarium, tepidarium y frigidarium, hipocaustos subterráneos con pilares de ladrillos refractarios y restos de pinturas murales pompeyanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','monumento','Si prefieres mantener la densidad y velocidad actuales de entrega','Si prefieres mantener la densidad y velocidad actuales de entrega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33025','monumento','Núcleos de población de Gozón','El término municipal incluye los siguientes núcleos de población: Luanco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33025','iglesia','Iglesia de Santa María de la Asunción de Luanco','Templo monumental barroco del siglo XVIII emplazado junto al mar, construido en sillería caliza regular. Su interior presenta una planta de nave única dividida por arcos torales, cubierta con bóvedas de crucería de diseño tardío y un magnífico retablo mayor churrigueresco de madera dorada de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33025','palacio','Palacio de Menéndez de la Pola','Residencia señorial barroca de los siglos XVII y XVIII ejecutada en sillería de cantería regular. Muestra una fachada simétrica articulada en dos cuerpos, flanqueada por dos torres cúbicas angulares de carácter defensivo y blasones heráldicos de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33026','palacio','Palacio de Miranda-Valdecarzana','Complejo residencial palaciego originario del siglo XV y profundamente reformado en estilo barroco a comienzos del siglo XVIII, edificado en sillería caliza compacta. Destaca su fachada principal con un portalón de medio punto almohadillado, capiteles jónicos y un gran blasón central timbrado con celada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33026','iglesia','Capilla de los Dolores','Joya del barroco clasicista del siglo XVIII atribuida al taller de Francisco de de la Riva, levantada en sillería arenisca de cantería regular. Presenta una planta rectangular con una cúpula interior sobre pechinas caladas, ornamentada con yeserías de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33026','monumento','Muralla Medieval y Torre de Villanueva','Vestigios del sistema defensivo de la villa del siglo XIII, consistentes en lienzos de mampostería pesada y la base cuadrangular de una gran torre vigía ejecutada en sillarejo regular calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33027','iglesia','Colegiata de San Salvador de Grandas','Templo de origen románico vinculado al Camino de Santiago Primitivo, reformado en las etapas barroca y neoclásica (siglos XVII y XVIII) en mampostería de pizarra local y esquinales de sillería arenisca. Conserva su portada románica abocinada de tres arquivoltas que apean sobre capiteles historiados, y un interior abovedado en cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33027','monumento','Castro de Chao Samartín','Yacimiento arqueológico de un asentamiento fortificado fortificado con ocupación desde la Edad del Bronce hasta la época romana (siglo II d. C.). Conserva defensas monumentales fosadas, lienzos de murallas en opus quadratum de piedra de pizarra y los cimientos de la gran domus romana dotada de estancias pavimentadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','monumento','Núcleos de población de Ibias','El término municipal incluye los siguientes núcleos de población: San Antolín de Ibias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','iglesia','Iglesia de San Antolín de Ibias','Fábrica de raíz románica rural con importantes adiciones barrocas, levantada en mampostería rústica de pizarra local y cuarcita compacta. Posee una cabecera de testero plano techada mediante bóveda de cañón apuntado y un porche lateral que cobija una portada de arco apuntado de dovelas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','palacio','Pazo de Tormaleo','Residencia señorial fortificada del siglo XVI ejecutada en bloque cúbico exento de piedra de pizarra y esquinales escuadrados calizos. Conserva saeteras defensivas en los paramentos inferiores, una galería de solana de madera de castaño machihembrada y blasones de armas de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33029','iglesia','Iglesia de Nuestra Señora de la Pastora','Templo rural barroco del siglo XVIII construido en rústica mampostería de pizarra con recercados de vanos en sillería arenisca compacta. Cuenta con una nave única rectangular rematada en testero plano y una robusta torre campanario de planta cuadrada con vanos de medio punto para los bronces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33029','monumento','Continuar con el orden alfabético estricto de los municipios asturianos','Continuar con el orden alfabético estricto de los municipios asturianos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33029','monumento','Dar prioridad a los municipios con patrimonio de la arquitectura prerrománica','Dar prioridad a los municipios con patrimonio de la arquitectura prerrománica','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33030','monumento','Núcleos de población de Illas','El término municipal incluye los siguientes núcleos de población: La Cañera y Callezuela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33030','iglesia','Iglesia de San Julián de Illas','Templo de origen medieval reedificado en el siglo XVIII con fábrica mixta de mampostería caliza y esquinales de sillería arenisca compacta. Su interior aloja una nave única con cubierta de armadura de madera de roble machihembrada y arcos fajones rebajados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33030','palacio','Palacio de Bárcena','Casona señorial de traza barroca rural (siglo XVII) construida en piedra de mampostería enlucida. Muestra un portalón adintelado de amplias dovelas, un blasón heráldico de perfecta labra y ventanas cuadrangulares recercadas con sillares regulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33031','monumento','Complejo Industrial de Nitrastur','Conjunto de arqueología industrial edificado en la década de 1940,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33031','iglesia','Iglesia de Santiago de Sama','Fábrica de estilo neogótico historicista construida a finales del siglo XIX en sillería de cantería regular. Presenta una fachada monumental con portalón abocinado de arquivoltas apuntadas, un gran rosetón calado de fina tracería y dos esbeltas torres campanario gemelas coronadas por agujas de piedra calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33031','monumento','Pozo María Luisa','Infraestructura minera del carbón de principios del siglo XX. Conserva su castillete monumental de estructura de celosía de hierro roblonado sobre cimientos de opus caementicium, la casa de máquinas en ladrillo visto aparejado a soga y tizón, y galerías de acceso abovedadas en mampostería de cuarcita.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33032','iglesia','Iglesia de San Nicolás de Villoria','Templo de origen románico (siglo XII) profundamente reformado en el siglo XVII en estilo barroco rural, levantado en cantería y mampostería regular caliza. Conserva de la traza original una portada abocinada meridional de tres arquivoltas de medio punto con capiteles historiados tallados a bisel con motivos zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33032','monumento','Torre del Condado','Ruinas consolidadas de una fortaleza defensiva medieval de planta cilíndrica (siglo XIV) construida en mampostería pesada de piedra caliza. Se conserva el lienzo inferior del muro perimetral dotado','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33033','iglesia','Iglesia de Santa Cristina de Lena','Joya de la arquitectura prerrománica asturiana del período ramirense (siglo IX) declarada Patrimonio de la Humanidad por la UNESCO, erigida en sillería caliza regular y mampostería basta. Su interior destaca por un iconostasio monumental de tres arcos de medio punto sobre columnas exentas de capiteles corintios y placas de cancel de mármol calado con celosías geométricas de rango internacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33033','palacio','Palacio de Revillagigedo en Campomanes','Complejo palaciego barroco del siglo XVII levantado en sillería arenisca compacta de excelente cantería. Presenta un volumen rectangular exento articulado en torno a un patio porticado central con columnas toscanas, rematando su fachada principal con un portalón adintelado moldurado y blasones de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','monumento','Núcleos de población de Llanera','El término municipal incluye los siguientes núcleos de población: Posada de Llanera y Lugo de Llanera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','palacio','Palacio de San Cucao (o Torre de Valdés)','** Complejo señorial fortificado del siglo XIV remodelado en el siglo XIX bajo cánones historicistas, edificado en sillería caliza compacta. Destaca su imponente torre del homenaje de planta cuadrada dotada de muros almenados, matacanes, saeteras originales y modillones en los voladizos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','iglesia','Iglesia de Santiago de Arlós','Templo románico de finales del siglo XII levantado en cantería de sillería arenisca. Muestra un ábside semicircular con canes de proa de barco lisos en el alero, una portada meridional abocinada de arcos apuntados lisos y una torre campanario robusta a los pies del templo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','iglesia','Basílica de Santa María de la Asunción','Templo monumental gótico de los siglos XIII al XV edificado en regular sillería caliza compacta. Destaca su fachada occidental con una gran portada abocinada de múltiples arquivoltas apuntadas y capiteles historiados de perfecta labra escultórica, y un interior abovedado con complejas crucerías estrelladas con terceletes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','monumento','Muralla Medieval y Torreón de Llanes','Recinto fortificado del siglo XIII construido en mampostería pesada de piedra caliza y esquinales escuadrados. El torreón es una sólida estructura cúbica exenta de carácter defensivo dotada de saeteras medievales y muros de gran espesor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','palacio','Palacio de el Cercado','Complejo palaciego barroco del siglo XVII fundado por el obispo Pedro de Junco Posada, levantado en sillería de cantería regular. Presenta un volumen rectangular articulado con portones adintelados moldurados y blasones heráldicos de extraordinaria factura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','monumento','Núcleos de población de Mieres','El término municipal incluye los siguientes núcleos de población: Mieres del Camino y Bustiello.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','monumento','Poblado Minero de Bustiello','Excepcional conjunto de arqueología industrial y urbanismo paternalista de finales del siglo XIX, construido por la Sociedad Hulla Española en ladrillo visto macizo y zócalos de mampostería caliza basta. Destaca la Iglesia de Santa Bárbara de traza historicista, las viviendas unifamiliares con entramados de madera de roble machihembrada y el sanatorio minero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','palacio','Palacio de Arriba de Cenera','Residencia señorial barroca del siglo XVIII ejecutada en sillería arenisca de perfecta labra. Presenta una fachada simétrica organizada en dos cuerpos con portalón central de medio punto, balconajes de forja artística y blasones de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','iglesia','Iglesia de San Juan Bautista','Fábrica historicista neorrománica de principios del siglo XX ejecutada en sillería de cantería fina, con una gran portada abocinada de arquivoltas molduradas e impostas ajedrezadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','monumento','Núcleos de población de Morcín','El término municipal incluye los siguientes núcleos de población: Santa Eulalia de Morcín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','monumento','Ermitas del Monsacro','Conjunto monumental de dos capillas medievales (siglo XII) situadas en la cumbre del monte sagrado, construidas en sillería caliza regular. La Ermita de Santiago presenta una inusual planta octogonal con ábside semicircular cubierta con cúpula de piedra y un interior abovedado, mientras que la Ermita de la Magdalena posee una planta rectangular con bóveda de cañón apuntado de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','iglesia','Iglesia de San Esteban de Morcín','Templo románico de finales del siglo XII reformado en el siglo XVIII, levantado en mampostería regular con esquinales escuadrados calizos y canecillos lisos en el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33039','monumento','Núcleos de población de Muros de Nalón','El término municipal incluye los siguientes núcleos de población: San Esteban de Pravia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33039','palacio','Palacio de Valdecarzana y Vallehermoso','Complejo residencial fortificado del siglo XV con reformas del siglo XVI en estilo renacentista plateresco, edificado en sillería caliza. Conserva una portada monumental con arco de medio punto de amplias dovelas radiales y un escudo de armas central tallado con volutas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33039','monumento','Cargaderos de Carbón de San Esteban de Pravia','Infraestructura industrial y portuaria de principios del siglo XX. Conserva las grúas de vapor exentas y los cargaderos de estructura de celosía de hierro roblonado sobre cimientos de opus caementicium, símbolos de la ingeniería portuaria minera de rango nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33040','palacio','Palacio de la Cogolla','Residencia señorial fortificada del siglo XVI con adiciones barrocas del siglo XVII, levantada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33040','iglesia','Iglesia de San Bartolomé de Nava','Fábrica neorrománica construida en el siglo XX para sustituir al templo medieval destruido, empleando sillería caliza en los arcos de articulación y sillarejo en los lienzos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33040','monumento','Si prefieres mantener el orden alfabético estricto establecido sin desvíos tipológicos','Si prefieres mantener el orden alfabético estricto establecido sin desvíos tipológicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','monumento','Castro de Mohías','Asentamiento fortificado de la cultura castreña (siglos I y II d. C.) ejecutado en muros exentos de rústica mampostería de pizarra local. Conserva las cimentaciones de viviendas de planta elíptica y rectangular con esquinas esquineadas redondeadas, además de fosos defensivos excavados directamente sobre el sustrato rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','palacio','Palacio de Arias Moinelo (Palacio de Anleo)','** Monumental residencia señorial originaria del siglo XIII y reedificada tras un incendio en el siglo XVI, construida en mampostería de pizarra y esquinales de sillería granítica. Presenta una planta en forma de L flanqueada por tres torres cúbicas provistas de almenas e hilera de modillones en sus aleros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33042','monumento','Torre del Reloj','Estructura monumental exenta erigida en el siglo XVII y reconstruida en el siglo XX, ejecutada en sillería caliza compacta y paños de ladrillo visto macizo. Su volumen cuadrangular de tres cuerpos decrecientes alberga un reloj monumental y remata en un chapitel de azulejería vidriada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33042','palacio','Palacio de Miraflores','Casona palaciega de estilo barroco del siglo XVIII construida con paramentos de mampostería enlucida y recercados de vanos en piedra arenisca de cantería regular. Cuenta con una portada adintelada flanqueada por pilastras molduradas y un blasón central tallado con volutas foliáceas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','monumento','Núcleos de población de Onís','El término municipal incluye los siguientes núcleos de población: Benia de Onís.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','iglesia','Iglesia de San Eulalia de Benia','Templo monumental gótico del siglo XV construido en sillería caliza grisácea. Presenta una planta de nave única rectangular con cabecera poligonal reforzada por contrafuertes exteriores, techada mediante una bóveda de crucería simple con nervios diagonales moldurados y claves de fina labra heráldica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','monumento','Torre de los Cereros','Torre defensiva bajomedieval del siglo XIV levantada en mampostería pesada de piedra caliza. Conserva su volumen cúbico original de carácter militar provisto de líneas de saeteras y dovelas radiales perfectas en su portada apuntada de acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','catedral','Catedral de San Salvador','Complejo catedralicio gótico de los siglos XIV al XVI de rango internacional, erigido en sillería caliza calada de extraordinaria labra. Destaca su esbelta torre calada rematada en aguja flamígera, el claustro gótico abovedado y la Cámara Santa (siglo IX, prerrománica Patrimonio de la Humanidad por la UNESCO), espacio absidial abovedado apuntalado por columnas exentas cuyos capiteles forman un apostolado escultórico de supremo virtuosismo anatómico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','iglesia','Iglesia de San Julián de los Prados (Santullano)','** Obra cumbre de la arquitectura prerrománica asturiana de la etapa alfonsina (siglo IX) Patrimonio de la Humanidad, construida en sillería regular y mampostería basta. Destaca su planta basilical con un gran crucero exento y una decoración pictórica mural polícroma interior en opus tectorium, que simula motivos arquitectónicos romanos de gran virtuosismo formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','iglesia','Iglesia de Santa María del Naranco','Antiguo aula regia palaciega del período ramirense (año 848) Patrimonio de la Humanidad por la UNESCO, tallada en perfecta','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','iglesia','Iglesia de San Miguel de Lillo','Templo prerrománico contemporáneo al Naranco, erigido en sillería arenisca. Conserva el tercio occidental de su planta basilical primigenia, destacando las jambas monolíticas caladas de la portada principal con relieves inspirados en un díptico consular romano, esculpidos con extraordinario virtuosismo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33045','monumento','Núcleos de población de Parres','El término municipal incluye los siguientes núcleos de población: Arriondas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33045','iglesia','Iglesia de San Martín de Cuadroveña','Templo de origen medieval reedificado en el siglo XVIII en estilo barroco rural empleando muros de gruesa mampostería y esquinales escuadrados calizos. Cuenta con una cabecera de testero plano abovedada en cañón y un gran pórtico perimetral sustentado sobre pies derechos de madera de roble machihembrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33045','palacio','Palacio de Nevares','Residencia señorial fortificada del siglo XVI levantada en sillería de cantería regular arenisca. Presenta una fachada simétrica flanqueada por una torre cuadrangular de carácter defensivo dotada de aspilleras bajomedievales y blasones de armas de fina labra heráldica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','monumento','Núcleos de población de Peñamellera Alta','El término municipal incluye los siguientes núcleos de población: Alles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','iglesia','Iglesia de San Pedro de Plecín','Ruinas monumentales de un templo románico del siglo XII edificado en sillería caliza de perfecta labra. Conserva una magnífica portada abocinada de cuatro arquivoltas apuntadas de transición, profusamente talladas con motivos geométricos y capiteles historiados de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','iglesia','Iglesia de San Pedro de Alles','Fábrica barroca del siglo XVIII financiada por capital indiano, levantada en cantería regular. Presenta una planta de cruz latina con una imponente torre campanario a los pies rematada por un cupulín calado y un interior abovedado con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33047','monumento','Núcleos de población de Peñamellera Baja','El término municipal incluye los siguientes núcleos de población: Panes y Buelles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33047','iglesia','Iglesia de San Juan de Ciliergo','Templo de origen románico tardío (siglo XIII) construido en sillería arenisca compacta y mampostería. Destaca su ábside semicircular con saeteras abocinadas e impostas ajedrezadas, y una portada meridional con capiteles de temática vegetal abstracta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33047','palacio','Palacio de la Cajiga en Abándames','Residencia palaciega barroca del siglo XVII ejecutada en piedra caliza regular. Muestra una fachada simétrica adintelada con un gran blasón central timbrado por celada y flanqueado por leones tenantes tallados con perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33048','iglesia','Iglesia de Santiago de Pesoz','Templo de raíz medieval modificado en el siglo XVIII, levantado en mampostería de pizarra local y cuarcita compacta. Posee una cabecera de testero plano techada mediante bóveda de cañón apuntado y una robusta torre campanario de planta cuadrada dotada de vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33048','palacio','Palacio de Ron','Complejo señorial fortificado del siglo XVII estructurado en torno a un patio porticado central, edificado en fábrica rústica de pizarra. Conserva una gran torre de flanqueo cuadrangular provista de aspilleras bajomedievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','monumento','Núcleos de población de Piloña','El término municipal incluye los siguientes núcleos de población: Infiesto y Villamayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','iglesia','Santuario de la Virgen de la Cueva','Conjunto sacro de origen medieval encastrado bajo una monumental visera rocosa caliza natural. La estructura barroca del siglo XVIII aprovecha el escarpe calizo como paramento posterior, combinando sillería de cantería y un pórtico de arquerías rebajadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','iglesia','Iglesia de Santa María de Villamayor','Vestigios de un monasterio románico del siglo XII del que subsiste el ábside semicircular y la portada absidial, labrados en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','monumento','Núcleos de población de Ponga','El término municipal incluye los siguientes núcleos de población: San Juan de Beleño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','iglesia','Iglesia de Santa María de Taranes','Templo de traza monumental barroca del siglo XVIII edificado en un entorno de alta montaña con fábrica de sillería caliza gris. Presenta una planta de cruz latina con crucero cubierto por cúpula sobre pechinas caladas y bóvedas de arista en los tramos de la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','monumento','Torre de Cazo','Estructura defensiva bajomedieval (siglo XIV) levantada en bloque cúbico exento de gruesa mampostería y esquinales escuadrados. Conserva líneas de saeteras originales y modillones en los voladizos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','iglesia','Iglesia de San Juan Evangelista de Santianes de Pravia','Obra cumbre de la etapa inicial de la arquitectura prerrománica asturiana (siglo VIII) mandada erigir por el rey Silo, construida en mampostería basta y esquinales de sillería caliza compacta. Conserva su planta basilical de tres naves separadas por pilares cuadrangulares de mampuesto y arcos de medio punto de ladrillo macizo, además del baptisterio original y fragmentos reconstruidos de su cancel de mármol calado de rango internacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','iglesia','Colegiata de Santa María la Mayor','Templo monumental del barroco clasicista (siglo XVIII) levantado en sillería de cantería regular por iniciativa de las familias de la villa. Alberga un interior cupulado de grandes proporciones con retablos churriguerescos de madera de nogal tallada y policromada de extraordinario virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','palacio','Palacio de Moutas','Conjunto palaciego del siglo XVIII anexo a la colegiata, edificado con paramentos de sillería arenisca compacta de perfecta labra. Presenta una fachada monumental simétrica con portón adintelado moldurado, balconajes de forja artística y blasones heráldicos de gran virtuosismo formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33052','monumento','Torre de Proaza (o Torre de los González Tuñón)','** Fortaleza defensiva bajomedieval (siglo XIV) ejecutada en sillería regular caliza y mampostería pesada. Presenta una inusual planta cilíndrica de cuatro cuerpos decrecientes con carácter marcadamente militar, provista de aspilleras de filiación bajomedieval, saeteras originales y modillones en los voladizos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33052','iglesia','Iglesia de Santa María de Bandujo','Templo de origen románico modificado en el siglo XVIII, levantado en aparejo rústico con pórtico perimetral de madera de roble machihembrada apoyado sobre basas pétreas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','monumento','Núcleos de población de Quirós','El término municipal incluye los siguientes núcleos de población: Bárzana y Llanuces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','iglesia','Iglesia de San Pedro de Arrojo','Templo románico de finales del siglo XII edificado en sillería arenisca regular y sillarejo calizo. Conserva el ábside semicircular con canecillos de proa de barco lisos en el alero, una portada apuntada abocinada de tres arquivoltas molduradas y capiteles de temática vegetal abstracta de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','palacio','Palacio de Miranda en Llanuces','Casona señorial barroca del siglo XVII ejecutada en bloque cúbico exento de piedra caliza con una gran fachada adintelada, balcones de forja artística y blasones de armas de fina labra heráldica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33054','iglesia','Iglesia de San Pedro de Nora','Joya de la arquitectura prerrománica asturiana del período alfonsino (siglo IX) Patrimonio de la Humanidad por la UNESCO, erigida en sillería regular y mampostería basta. Presenta una planta basilical de tres naves separadas por arquerías de medio punto sobre pilares exentos y un ábside triple con celosías caladas calizas e hileras de ladrillo macizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33054','monumento','Villa Romana de Andallón','Yacimiento arqueológico con estructuras consolidadas en opus quadratum de los siglos I a. C. al IV d. C. Conserva tramos de la zona','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','monumento','Núcleos de población de Ribadedeva','El término municipal incluye los siguientes núcleos de población: Colombres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','monumento','Quinta de Guadalupe (Archivo de Indianos)','** Obra cumbre de la arquitectura ecléctica e indiana de principios del siglo XX, erigida con materiales nobles y sillería caliza compacta de perfecta labra técnica. Presenta un palacio principal de tres plantas con salones decorados con estucos dorados, mármoles exentos y galerías voladas de forja artística y carpintería fina moldurada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','monumento','Cueva del Pindal','Estación arqueológica de arte de la cornisa cantábrica declarada Patrimonio de la Humanidad por la UNESCO. Conserva representaciones parietales incisas y polícrómas mediante pigmentos de óxido de hierro de gran virtuosismo formal, destacando la figura de un mamut.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','monumento','Cueva de Tito Bustillo','Santuario arqueológico de arte paleolítico de rango internacional, declarado Patrimonio de la Humanidad por la UNESCO. Conserva el "Camarín de las Vulvas" y el monumental "Panel Principal", con representaciones zoomorfas polícrómas mediante óxidos de hierro y grabados incisos sobre roca calcárea de supremo virtuosismo técnico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','palacio','Palacio de Prieto-Cutre','Sede del consistorio, edificio civil renacentista del siglo XVI tallado en sillería caliza compacta. Destaca su fachada plateresca con un gran portalón de medio punto cobijado por arquivoltas molduradas, ventanas conopiales recercadas y blasones heráldicos de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','iglesia','Iglesia de Santa María de Barra','Ruinas consolidadas de un templo románico tardío (siglo XIII) ejecutado en mampostería caliza basta y esquinales de cantería regular, conservando la traza del arco triunfal apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','monumento','Núcleos de población de Riosa','El término municipal incluye los siguientes núcleos de población: La Vega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','monumento','Poblado Minero de Rioseco','Complejo de arqueología industrial del carbón del siglo XIX erigido en mampostería basta de piedra de caliza y pizarra local. Conserva las bocaminas reforzadas con arcos de medio punto de ladrillo macizo, los talleres mecánicos y los cargaderos de gravedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','iglesia','Iglesia de Santa María de Riosa','Fábrica neoclásica rural del siglo XVIII levantada en sillería regular y sillarejo. Cuenta con una nave única rectangular con cabecera de testero plano abovedada en cañón y una robusta torre campanario de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','iglesia','Colegiata de Santa María la Mayor','Templo monumental gótico-renacentista del siglo XVI erigido en regular sillería caliza calada. Alberga en su interior el suntuoso mausoleo del arzobispo Fernando de Valdés Salas, obra cumbre del Renacimiento español esculpida por Pompeyo Leoni en alabastro polícromo con extraordinario virtuosismo anatómico y perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','monumento','Torre de los Valdés','Fortaleza defensiva bajomedieval del siglo XIV ejecutada en mampostería pesada y esquinales de cantería fina. Es una sólida estructura cúbica de tres cuerpos de carácter militar dotada de adarves almenados, matacanes, saeteras originales y modillones en los voladizos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','iglesia','Iglesia de San Martín de Salas','Fábrica prerrománica reedificada en el siglo X, reconstruida en estilo barroco. Conserva empotradas en sus muros las célebres estelas epigráficas y decorativas prerrománicas labradas a bisel con motivos entrelazados y cruces de la Victoria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33060','monumento','Pozo San Vicente','Infraestructura minera convertida en museo, ejemplo singular de la ingeniería extractiva del carbón de principios del siglo XX. Conserva su castillete monumental de estructura de celosía de hierro roblonado sobre cimientos de opus caementicium y la casa de máquinas en ladrillo visto aparejado a soga y tizón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33060','iglesia','Iglesia de San Martín de Tours','Fábrica historicista neogótica de finales del siglo XIX ejecutada en sillería caliza compacta. Presenta una fachada monumental con portalón abocinado de arquivoltas apuntadas, un rosetón calado de fina tracería y dos esbeltas torres campanario coronadas por agujas caladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33061','palacio','Palacio de Guzmanes en Mon','Complejo señorial de la etapa barroca (siglos XVII y XVIII) edificado sobre estructuras defensivas previas en rústica fábrica de pizarra del occidente asturiano. Destaca su fachada principal con un portalón adintelado moldurado de sillería de cantería regular arenisca y un gran blasón con orlas de volutas foliáceas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33061','iglesia','Iglesia de San Martín','Templo rural del siglo XVIII levantado en aparejo de pizarra y esquinales escuadrados calizos. Alberga una nave única rectangular con cabecera de testero plano techada mediante una armadura de madera de castaño con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','palacio','Palacio de El Lojo','Casona señorial barroca del siglo XVIII construida con muros de mampostería de pizarra local y recercados de vanos en sillería arenisca compacta. Muestra una planta cúbica exenta flanqueada por una torre cuadrangular de carácter defensivo dotada de aspilleras bajomedievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','iglesia','Iglesia de San Salvador','Fábrica neoclásica rural del siglo XVIII que cuenta con una nave rectangular única y una robusta torre campanario de planta cuadrada con vanos de medio punto para los bronces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','monumento','Conjunto Etnográfico de Mazonovo','Instalación protoindustrial destinada al forjado del hierro mediante martillo de gravedad accionado por energía hidráulica. Conserva las canalizaciones de captación talladas en piedra de sillería basta, los cárcavos y el mazo sobre un bloque monolítico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','palacio','Casona de la Pruida','Residencia señorial barroca del siglo XVII ejecutada en piedra de pizarra. Presenta un portalón de acceso con dovelas radiales perfectas y blasones heráldicos labrados con orlas de volutas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33064','monumento','Núcleos de población de Santo Adriano','El término municipal incluye los siguientes núcleos de población: Tuñón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33064','iglesia','Iglesia de Santo Adriano de Tuñón','Joya de la arquitectura prerrománica asturiana correspondiente a la etapa postramirense, consagrada en el año 891 por Alfonso III el Magno y declarada Monumento Nacional, erigida en sillería regular y mampostería basta. Muestra una planta basilical de tres naves separadas por pilares cuadrangulares de mampuesto y arcos de medio punto de ladrillo macizo, un ábside triple abovedado con pinturas murales litúrgicas originales en opus tectorium de gran virtuosismo formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33065','iglesia','Iglesia de Santa María de la Asunción de Narzana','Templo románico de finales del siglo XII edificado en regular fábrica de sillería arenisca compacta. Conserva su ábside semicircular con canecillos de proa de barco lisos en el alero y una portada meridional abocinada de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33065','palacio','Palacio de los de la Riva','Casona señorial de traza barroca (siglo XVII) construida en piedra de mampostería enlucida con recercados de vanos en sillares regulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','monumento','Núcleos de población de Siero','El término municipal incluye los siguientes núcleos de población: Pola de Siero, Lugones y El Berrón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','iglesia','Iglesia de San Esteban de Aramil','Joya de la arquitectura románica rural del siglo XII levantada en perfecta fábrica de sillería arenisca. Posee un ábside semicircular abovedado en horno con saeteras flanqueadas por columnillas e impostas ajedrezadas, y una magnífica portada meridional abocinada de tres arquivoltas con capiteles historiados de gran virtuosismo escultórico popular que representan motivos zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','palacio','Palacio de Celles','Ruinas monumentales de un palacio barroco de finales del siglo XVII de colosales proporciones, ejecutado en fina cantería regular arenisca. Destaca su fachada clasicista de orden gigante con pilastras jónicas cajeadas, grandes portones adintelados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','monumento','Puente de Colloto','Infraestructura viaria de origen medieval levantada sobre el río Nora en sillería caliza compacta y mampostería. Consta de tres arcos de medio punto provistos de tajamares triangulares aguas arriba y un pavimento empedrado con cantos rodados compactados con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33067','monumento','Torre de Villamorey (o Castillo de Sobrescobio)','** Ruinas consolidadas de una fortaleza defensiva medieval del siglo XII emplazada sobre un escarpe rocoso cuarcítico. Subsiste el lienzo inferior de una gran torre cuadrangular de mampostería pesada y esquinales escuadrados, que controlaba el paso estratégico de la cuenca alta del río Nalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33067','iglesia','Iglesia de Santa María de Oviñana','Templo barroco rural del siglo XVIII levantado en mampostería enlucida con pórtico perimetral de madera de roble machihembrada, cabecera de testero plano y una robusta espadaña de dos vanos calados para los bronces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33068','monumento','Brañas de Teito de Somiedo','Excepcional conjunto de arquitectura popular e industrial ganadera prehistórica de montaña. Comprende decenas de cabañas de pastores exentas de planta rectangular ejecutadas en gruesa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33068','iglesia','Iglesia de San Pedro de Pola de Somiedo','Templo de traza barroca rural (siglo XVIII) construido en piedra caliza regular. Su nave única rectangular se cubre con una bóveda de cañón con lunetos y posee una robusta torre campanario de planta cuadrada a los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33071','monumento','Conjunto Etnográfico de Os Teixóis','Complejo protoindustrial hidráulico del siglo XVIII recuperado con rigurosa especificidad técnica. Construido en rústica fábrica de pizarra local, conserva un mazo de forja, un molino harinero, un batán y una pequeña central eléctrica movidos por captaciones de agua sobre canales tallados en sillería basta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33071','monumento','Castro de Taramundi (Os Castros)','** Asentamiento fortificado fortificado de la cultura castreña del siglo I d. C. con ocupación romana. Conserva las cimentaciones de murallas perimetrales de pizarra, saunas rituales con cámaras absidiales monolíticas y los muros exentos de viviendas circulares de perfecta labra popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','iglesia','Colegiata de San Pedro de Teverga','Obra cumbre de la transición del prerrománico al románico temprano (siglo XI) de rango nacional, construida en sillería caliza gris de perfecta labra. Presenta una planta basilical de tres','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','palacio','Palacio de Valdecarzana','Ruinas de la residencia señorial medieval (siglo XV) ejecutada en mampostería pesada y sillería regular caliza. Conserva su fachada de carácter militar provista de un portón central de medio punto con dovelas radiales perfectas y saeteras defensivas inferiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33073','iglesia','Monasterio de Santa María la Real de Obona','Cenobio benedictino de origen medieval reconstruido en el siglo XVIII bajo cánones neoclásicos y herrerianos, edificado en sillería de piedra arenisca y pizarra de excelente labra. La iglesia conserva su estructura románica del siglo XII con triple ábside semicircular, bóvedas de cañón apuntado y capiteles historiados de gran virtuosismo formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33073','iglesia','Iglesia de San Pedro de Tineo','Antiguo templo del convento de San Francisco (siglo XIII) ejecutado en sillería caliza compacta. Conserva elementos del gótico temprano como su portada abocinada de arcos apuntados lisos, arcos torales cuadrangulares y un interior abovedado con crucería simple que alberga sepulcros heráldicos de sillería tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','monumento','Núcleos de población de Valdés','El término municipal incluye los siguientes núcleos de población: Luarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','palacio','Palacio del Marqués de Ferrera','Complejo palaciego barroco del siglo XVI con importantes ampliaciones del siglo XVIII en Luarca, construido en mampostería de pizarra local y recercados de vanos en sillería granítica. Presenta una planta rectangular con torres cúbicas angulares almenadas, patios interiores porticados y un portón adintelado moldurado de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','ermita','Ermita de la Virgen de la Blanca y Faro de Luanco','Conjunto sacro y civil de origen medieval emplazado sobre la atalaya caliza. La ermita, reformada en el siglo XVIII, muestra muros de mampostería basta enlucida con pórtico perimetral de madera de castaño y arcos de medio punto bien escuadrados calizos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33074','palacio','Palacio de Meredo','Residencia señorial barroca del siglo XVIII edificada en el occidente asturiano con rústica fábrica de pizarra y esquinales de sillería arenisca compacta. Cuenta con una fachada simétrica organizada en dos cuerpos con portalón central de medio punto, balcones de forja artística y blasones heráldicos de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33074','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo neoclásico del siglo XIX construido en sillería regular y sillarejo, dotado de una torre campanario robusta a los pies con vanos apuntados para los bronces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','iglesia','Iglesia de San Salvador de Valdediós (El Conventín)','** Obra cumbre de la etapa postramirense de la arquitectura prerrománica asturiana (consagrada en el año 893), declarada Patrimonio de la Humanidad por la UNESCO y erigida en sillería regular y mampostería basta caliza. Destaca su planta basilical de tres naves con un porche lateral exento, ábside triple con celosías caladas de mármol y pinturas murales al fresco de extraordinario virtuosismo geométrico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','iglesia','Monasterio de Santa María de Valdediós','Conjunto monástico cisterciense del siglo XIII colindante al Conventín, edificado en sillería caliza de perfecta labra. La iglesia abacial presenta una imponente cabecera de tres ábsides semicirculares abovedados en horno, un gran rosetón de fina tracería calada y un claustro clásico con arquerías rebajadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','iglesia','Iglesia de Santa María de la Oliva','Joya de la transición del románico tardío al gótico inicial (siglo XIII) situada en el casco urbano, tallada en sillería arenisca compacta. Posee una magnífica portada abocinada de arcos apuntados de transición de múltiples arquivoltas profusamente esculpidas e impostas ajedrezadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33078','monumento','Núcleos de población de Yernes y Tameza','El término municipal incluye los siguientes núcleos de población: Villabre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33078','iglesia','Iglesia de Santa María de Tameza','Templo rural de origen medieval profundamente reformado en el siglo XVIII, levantado en aparejo rústico de cuarcita local con esquinales de piedra labrada. Cuenta con una nave única rectangular con cabecera de testero plano y techumbre de madera de roble machihembrada con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10002','monumento','Núcleos de población de Bárcena de Cicero','El término municipal incluye los siguientes núcleos de población: Gama, Treto y Adal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10002','palacio','Palacio de Rugama en Bárcena','Complejo residencial palaciego barroco del siglo XVIII levantado en perfecta sillería regular caliza. Consta de una fachada monumental flanqueada por una torre cúbica defensiva dotada de saeteras, un portón adintelado moldurado flanqueado por pilastras cajeadas y un blasón heráldico labrado con volutas foliáceas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10002','palacio','Palacio de Colina en Gama','Casona señorial barroca del siglo XVII ejecutada en piedra de cantería regular. Presenta una portalada monumental exenta de acceso con arco de medio punto de amplias dovelas radiales y grandes escudos de armas de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','monumento','Núcleos de población de Cabuérniga','El término municipal incluye los siguientes núcleos de población: Carmona, Terán y Valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','palacio','Palacio de los Díaz de Cossío y Mier en Carmona','Conjunto monumental barroco del siglo XVIII ejecutado en sillería arenisca de perfecta labra de cantería regular. Presenta una fachada de gran longitud estructurada en dos pisos con portón central adintelado, balconajes de forja artística y una arquería de arcos de medio punto en la planta baja, rematada por dos grandes blasones heráldicos exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','iglesia','Iglesia de Santa Eulalia de Terán','Templo barroco del siglo XVII levantado sobre una base mampuesta con esquinales de sillería escuadrada caliza. Alberga una nave rectangular cubierta por bóveda de cañón con lunetos y una cabecera de testero plano que custodia un retablo churrigueresco de madera de nogal finamente tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','monumento','Núcleos de población de Camaleño','El término municipal incluye los siguientes núcleos de población: Santo Toribio de Liébana, Mogrovejo y Espinama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','iglesia','Monasterio de Santo Toribio de Liébana','Cenobio gótico del siglo XIII de rango e internacional, edificado en sillería caliza compacta de excelente cantería. La iglesia presenta una planta de tres naves con bóvedas de crucería simple y un ábside poligonal; destaca la Puerta del Perdón, un acceso abocinado gótico con arquivoltas apuntadas y capiteles historiados de gran virtuosismo escultórico. Custodia la reliquia del Lignum Crucis.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','monumento','Torre de Mogrovejo','Fortaleza militar medieval del siglo XIII erigida en bloque cúbico exento de gruesa mampostería caliza y esquinales de sillería escuadrada arenisca. Presenta una planta cuadrada dotada de muros almenados, líneas de saeteras originales y modillones en los voladizos superiores, flanqueada por una casona señorial barroca posterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','monumento','Núcleos de población de Castañeda','El término municipal incluye los siguientes núcleos de población: Socobio, Pomaluengo y Villabáñez.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','iglesia','Colegiata de Santa Cruz de Castañeda','Obra cumbre del románico pleno cántabro (siglo XII) de rango nacional, construida en sillería caliza compacta y arenisca arenisca de perfecta labra. Presenta una planta de cruz latina con un imponente crucero coronado por un cimborrio octogonal abovedado sobre pechinas caladas, un ábside semicircular con arquerías ciegas exentas e impostas ajedrezadas, y capiteles historiados de extraordinario virtuosismo escultórico popular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','palacio','Palacio de Larrínaga','Complejo residencial monumental de estilo ecléctico indiano erigido a principios del siglo XX, tallado en fina cantería regular con galerías exentas de arcos rebajados y rejerías de forja artística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','monumento','Núcleos de población de Cillorigo de Liébana','El término municipal incluye los siguientes núcleos de población: Tama, Lebeña y Castro-Cillorigo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','iglesia','Iglesia de Santa María de Lebeña','Obra maestra cumbre de la arquitectura mozárabe del siglo X (año 925) de rango internacional, construida en sillería regular y mampostería calcárea colocada a soga y tizón. Su interior se compartimenta en espacios cuadrados mediante arcos de herradura perfectos que apoyan sobre columnas adosadas con capiteles de talla corintia asturiense; posee bóvedas de cañón exentas dispuestas en direcciones longitudinales y transversales de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','palacio','Casona de Bedoya en Bedoya','Residencia señorial fortificada del siglo XVI con planta cúbica exenta en piedra de sillería arenisca, provista de un portón central de medio punto dovelado y ventanas conopiales molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39023','palacio','Palacio de el Infantado (o de Alvarado)','** Residencia palaciega de estilo renacentista herreriano del siglo XVI, edificada en perfecta sillería caliza gris. Presenta un diseño de líneas severas y geométricas con una fachada adintelada flanqueada por dos cuerpos cúbicos exentos, un gran blasón central tallado con golas y una portalada monumental exenta con pilastras jónicas cajeadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39023','iglesia','Iglesia de San Juan Bautista','Fábrica del siglo XVI de transición gótico-renacentista construida en cantería regular. Alberga una amplia nave única con capillas hornacinas laterales techada mediante bóvedas de crucería estrellada con terceletes y ligaduras de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','monumento','Núcleos de población de Corvera de Toranzo','El término municipal incluye los siguientes núcleos de población: Alceda, Ontaneda y San Vicente de Toranzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','palacio','Palacio de Ceballos el Caballero en Alceda','Complejo palaciego barroco del siglo XVIII tallado en sillería arenisca compacta de perfecta labra. Presenta una fachada monumental de dos pisos con un gran portalón','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','palacio','Casona de Bustillo en Ontaneda','Residencia señorial barroca del siglo XVII ejecutada en fábrica mixta de mampostería enlucida y sillería regular caliza en vanos, caracterizada por su gran portalada exenta con arco de medio punto de amplias dovelas radiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39029','iglesia','Monasterio de San Sebastián de Hano','Cenobio capuchino fundado en el siglo XIV y reedificado en el siglo XVII en estilo barroco severo, levantado en cantería arenisca. La iglesia conventual presenta una fachada desornamentada de sillería de líneas clasicistas y un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39029','monumento','Torre de Guevara','Ruinas consolidadas de una fortaleza defensiva medieval del siglo XIV de planta cuadrangular, ejecutada en mampostería pesada de piedra caliza y esquinales escuadrados, conservando hilera de modillones en sus lienzos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','monumento','Núcleos de población de Liendo','El término municipal incluye los siguientes núcleos de población: Hazas e Iseca Vieja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','iglesia','Iglesia de Nuestra Señora de la Asunción de Hazas','Templo monumental iniciado en el siglo XVI en estilo gótico-renacentista y ampliado en la etapa barroca, edificado en sillería caliza compacta. Destaca su suntuosa fachada de proporciones catedralicias clasicistas y un interior cupulado con bóvedas de crucería estrellada cuyos nervios apean en imponentes pilares cilíndricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','palacio','Palacio de Albo en Iseca Vieja','Casona señorial de traza barroca (siglo XVII) construida en piedra arenisca','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','iglesia','Iglesia de San Pedro','Templo monumental iniciado en el siglo XVI en estilo gótico-renacentista y completado en el período barroco, edificado en sillería caliza compacta. Custodia en su presbiterio el célebre Santo Cristo de la Agonía, obra cumbre de la imaginería barroca andaluza atribuida a la escuela de Pedro de Mena, tallada en madera policromada con un extraordinario virtuosismo anatómico de rango nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','palacio','Palacio de el Conde de Limpias (o del General Alvear)','** Residencia palaciega de estilo ecléctico e historicista de finales del siglo XIX, levantada en sillería arenisca y mampostería enlucida. Destaca su fachada simétrica con ventanales moldurados, torreones cúbicos angulares y balconajes de forja artística.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','monumento','Núcleos de población de Luena','El término municipal incluye los siguientes núcleos de población: San Miguel de Luena y Resconorio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','iglesia','Iglesia de San Miguel de Luena','Templo barroco rural del siglo XVII construido en aparejo rústico de piedra caliza y esquinales escuadrados de sillería arenisca. Su interior consta de una nave única rectangular cubierta mediante bóvedas de cañón con lunetos y posee una robusta torre campanario adosada al hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','monumento','Cabañas Pasiegas de Resconorio','Conjunto de arquitectura popular e industrial ganadera de montaña. Estructuras exentas de mampostería basta de caliza calada con cubiertas a dos aguas de losas de pizarra y hastiales de madera de roble machihembrada con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','monumento','Núcleos de población de Mazcuerras','El término municipal incluye los siguientes núcleos de población: Cos y Luzmela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','palacio','Casona de las de Luzmela (Residencia de Concha Espina)','** Casona señorial del siglo XVII representativa de la arquitectura civil barroca montañesa. Construida en sillería regular arenisca y mampostería enlucida, destaca','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','monumento','Torre de los de Hoyos en Cos','Ruinas consolidadas de una estructura defensiva bajomedieval (siglo XIV) de planta cuadrangular, ejecutada en mampostería pesada y esquinales escuadrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39043','monumento','Núcleos de población de Meruelo','El término municipal incluye los siguientes núcleos de población: San Miguel de Meruelo y San Bartolomé.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39043','iglesia','Iglesia de San Miguel de Meruelo','Templo de origen gótico final (siglo XVI) con ampliaciones barrocas, edificado en fábrica mixta de mampostería caliza y esquinales de sillería escuadrada. Su única nave aloja bóvedas de crucería estrellada con terceletes y claves lisas, sustentadas sobre pilastras adosadas de sección cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39043','monumento','Puente de la Venera','Infraestructura viaria medieval levantada sobre el río Campiazo en cantería regular arenisca. Consta de un gran arco rebajado y un pavimento de cantos rodados compactados con mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','monumento','Núcleos de población de Miera','El término municipal incluye los siguientes núcleos de población: Mirones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo monumental del siglo XVI de colosales proporciones para su entorno rural, apodado "La Catedral del Miera", edificado en sillería caliza compacta. Destaca su anchísima nave gótico-renacentista coronada por complejas bóvedas de crucería estrellada con terceletes y ligaduras de gran virtuosismo escultórico geométrico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','monumento','Cueva de Sopeña','Estación arqueológica con ocupación del Paleolítico Superior que contiene cimientos habitacionales rústicos y material lítico encastrado en un talud de caliza grisácea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39046','monumento','Núcleos de población de Molledo','El término municipal incluye los siguientes núcleos de población: Silió y Helguera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39046','iglesia','Iglesia de San Facundo y San Primitivo de Silió','Joya del románico pleno del siglo XII declarada Monumento Nacional, erigida en sillería caliza de perfecta labra. Presenta un ábside semicircular excepcional con columnas adosadas, capiteles historiados de gran virtuosismo escultórico popular y un alero soportado por una densa serie de canecillos profusamente labrados con motivos zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39046','ermita','Ermita de Santa Leocadia de Helguera','Templo mozárabe del siglo X erigido en regular fábrica de sillería colocada a soga y tizón (opus quadratum). Conserva un ábside semicircular con un arco triunfal de herradura perfecta sobre capiteles de temática vegetal abstracta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','monumento','Núcleos de población de Penagos','El término municipal incluye los siguientes núcleos de población: Cabárceno y Sobarzo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','iglesia','Iglesia de San Jorge de Penagos','Fábrica de transición gótico-renacentista del siglo XVI levantada en sillería arenisca regular y mampuesto basta. Presenta una cabecera poligonal reforzada con potentes contrafuertes y una techumbre de nave única resuelta mediante bóvedas de crucería estrellada con terceletes de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','palacio','Palacio de Miranda','Residencia señorial de la etapa barroca (siglo XVII) construida en piedra caliza regular con paramentos enlucidos. Destaca su portalón central adintelado moldurado flanqueado por pilastras cajeadas y un blasón de armas de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','monumento','Núcleos de población de Peñarrubia','El término municipal incluye los siguientes núcleos de población: Cicera, La Hermida y Linares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','monumento','Torre de Linares','Fortaleza defensiva bajomedieval (siglo XIV) integrada en el sistema de torres vigía del desfiladero de La Hermida, edificada en bloque cúbico de sillería caliza gris y mampostería pesada. Conserva sus muros almenados defensivos, saeteras originales en los paramentos inferiores y modillones en los voladizos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','iglesia','Iglesia de San Juan Cantius de Cicera','Templo barroco rural del siglo XVII levantado en aparejo rústico con pórtico perimetral de madera de roble machihembrada apoyado sobre basas pétreas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','monumento','Núcleos de población de Pesaguero','El término municipal incluye los siguientes núcleos de población: Caloca y Lomeña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','iglesia','Iglesia de la Asunción de Caloca','Joya del románico rural de alta montaña (siglo XIII) construida en sillería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','ermita','Ermita de Nuestra Señora de la Asunción de Lomeña','Santuario medieval exento que custodia en su interior una talla gótica de la Virgen esculpida en madera de peral policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39051','iglesia','Iglesia de San Miguel','Templo de origen gótico (siglo XIV) modificado en el siglo XVI, edificado en sillería arenisca compacta. Alberga una nave única rectangular cubierta con bóveda de crucería simple con arcos torales rectangulares, y posee una robusta torre campanario de planta cuadrada adosada al hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39051','monumento','Calzada de los Blendios (Tramo local)','Vestigios consolidados de infraestructura viaria medieval ejecutada en mampostería regular caliza con pavimentación de cantos rodados compactados con cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39054','monumento','Núcleos de población de Polanco','El término municipal incluye los siguientes núcleos de población: Rinconeda y Rumoroso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39054','palacio','Casa-Palacio de José María de Pereda','Residencia señorial barroca del siglo XVIII con reformas decimonónicas, edificada en sillería de cantería regular arenisca y mampostería enlucida. Destaca su fachada simétrica con un gran portalón adintelado moldurado, solana superior de madera de roble machihembrada con modillones y un escudo de armas familiar de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39054','iglesia','Iglesia de San Pedro Apóstol de Rumoroso','Fábrica gótico-renacentista del siglo XVI levantada en aparejo de caliza regular. Alberga una bóveda de crucería estrellada con terceletes y ligaduras cuyos nervios apean en artísticas ménsulas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','monumento','Núcleos de población de Ramales de la Victoria','El término municipal incluye los siguientes núcleos de población: Gibaja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','monumento','Zona Arqueológica de Ramales','Complejo de cuevas prehistóricas declaradas Patrimonio de la Humanidad por la UNESCO (Cueva de Covalanas y Cueva de El Mirón). Destaca el panel de ciervas de Covalanas, ejecutado con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','palacio','Palacio de Revillagigedo en Gibaja','Mansión señorial barroca del siglo XVII levantada en sillería de cantería regular. Presenta una fachada rectangular simétrica con portalón adintelado flanqueado por pilastras jónicas cajeadas, balconajes de forja artística y blasones de armas de fina labra heráldica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39058','monumento','Núcleos de población de Rasines','El término municipal incluye los siguientes núcleos de población: Cereceda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39058','iglesia','Iglesia de San Andrés de Cereceda','Templo gótico monumental de transición al plateresco (siglo XVI), edificado en perfecta sillería caliza gris. El interior alberga bóvedas de crucería estrellada de gran virtuosismo escultórico y un presbiterio con relieves manieristas calados de excelente labra anatómica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39058','monumento','Plaza de Toros Cuadrada de Rasines','Singular coso taurino de mampostería basta edificado en el siglo XVIII, único en la provincia por su trazado perimetral cuadrangular regular asentado sobre zócalos pétreos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39059','iglesia','Iglesia de San Sebastián','Templo monumental del barroco clasicista del siglo XVIII (año 1774) edificado en sillería arenisca de perfecta labra regular. Destaca su imponente fachada principal y una torre campanario robusta rematada por un cupulín calado; el interior alberga bóvedas de cañón con lunetos soportadas por colosales pilastras jónicas y yeserías de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39059','palacio','La Casona (o Palacio de los de Cos)','** Edificio civil barroco del siglo XVIII reconstruido tras un incendio, ejecutado en sillería de cantería regular. Presenta una planta rectangular con una gran portalada adintelada moldurada, balconajes de forja artística y una galería superior de arquerías de estilo aragonés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39062','monumento','Núcleos de población de Ribamontán al Monte','El término municipal incluye los siguientes núcleos de población: Hoz de Anero, Villaverde de Pontones y Omoño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39062','palacio','Palacio de los de Rigada en Hoz de Anero','Obra cumbre de la arquitectura civil barroca montañesa del siglo XVII (año 1680) de rango nacional, construida en sillería arenisca compacta. Presenta una fachada monumental flanqueada por dos torres cúbicas angulares provistas de saeteras, portalones adintelados moldurados y una portalada exenta con blasones de gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39062','iglesia','Iglesia de Santa María de Toraya','Templo de origen gótico (siglo XVI) con ampliaciones barrocas, edificado en cantería regular. El espacio interior destaca por sus amplias bóvedas de crucería estrellada con terceletes y ligaduras cuyos nervios apean en pilares cilíndricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','monumento','Núcleos de población de Rionansa','El término municipal incluye los siguientes núcleos de población: Puentenansa y Cosío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','palacio','Torre y Casonas de Cosío','Conjunto histórico representativo de la arquitectura señorial y militar de los siglos XV al XVIII. Destaca la torre bajomedieval cúbica exenta de mampostería pesada y esquinales de sillería escuadrada con saeteras originales, flanqueada por palacetes barrocos con grandes blasones heráldicos de perfecta labra de cantería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','monumento','Cueva de El Soplao (Infraestructuras mineras)','Complejo de arqueología industrial minera del siglo XIX, conservando las bocaminas reforzadas con arcos de medio punto de ladrillo macizo, los talleres mecánicos y la red de ferrocarril minero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','monumento','Continuar con el orden alfabético estricto de la provincia','Continuar con el orden alfabético estricto de la provincia','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39064','monumento','Núcleos de población de Riotuerto','El término municipal incluye los siguientes núcleos de población: La Cavada y Angustina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39064','monumento','Real Fábrica de Artillería de La Cavada (Arco de Carlos III)','Monumento neoclásico de ingeniería militar y arqueología industrial del siglo XVIII (año 1784) de rango nacional, erigido en sillería caliza compacta. El arco de triunfo clasicista muestra pilastras jónicas cajeadas, inscripciones conmemorativas y un entablamento completo rematado por el escudo de armas reales labrado con gran virtuosismo escultórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39064','iglesia','Iglesia de San Juan Bautista de La Cavada','Fábrica de proporciones monumentales iniciada en el siglo XVII y reformada en el XVIII, ejecutada en sillería arenisca. Su planta de cruz latina alberga bóvedas de cañón con lunetos y un crucero cubierto por cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','monumento','Núcleos de población de Ruiloba','El término municipal incluye los siguientes núcleos de población: Ruiloba, Liandres y Pando.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','iglesia','Iglesia de la Asunción de la Virgen','Templo barroco de finales del siglo XVII erigido en sillería regular caliza y mampuesto. Destaca su esbelta torre campanario de planta cuadrada rematada por un cuerpo octogonal con vanos de medio punto y capitel calado de piedra arenisca, y un interior abovedado con lunetos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','monumento','Casas Señoriales de Liandres y Pando','Conjunto homogéneo de arquitectura civil tradicional montañesa de los siglos XVII y XVIII. Presentan fachadas exentas de sillería de cantería regular con portalones adintelados, solanas de madera de roble con modillones y escudos heráldicos labrados a bisel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','monumento','Núcleos de población de Ruesga','El término municipal incluye los siguientes núcleos de población: Riva y Ogarrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','palacio','Palacio de los de Arredondo en Riva','Residencia señorial de la etapa barroca (siglo XVII) construida en piedra arenisca de cantería regular. Presenta una fachada rectangular simétrica con un gran portalón central de medio punto de amplias dovelas radiales, balcones de forja artística y blasones heráldicos de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','iglesia','Iglesia de San Félix de Ogarrio','Templo gótico final (siglo XVI) edificado en fábrica mixta de mampostería caliza y esquinales escuadrados, que alberga un interior cubierto por bóvedas de crucería estrellada con terceletes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39069','monumento','Núcleos de población de San Felices de Buelna','El término municipal incluye los siguientes núcleos de población: Rivero, Llano y Mata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39069','monumento','Torre de Pero Niño en Llano','Fortaleza militar medieval del siglo XIV declarada Bien de Interés Cultural, erigida en bloque cúbico exento de gruesa mampostería y esquinales escuadrados de sillería arenisca. Cuenta con tres plantas de carácter defensivo dotadas de adarves almenados, líneas de saeteras originales y modillones en los voladizos superiores de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39069','iglesia','Iglesia de San Felices de Rivero','Fábrica monumental iniciada en el siglo XVI en estilo gótico-renacentista, construida en perfecta cantería regular caliza. El interior destaca por sus amplias bóvedas de crucería estrellada con terceletes y ligaduras cuyos nervios apean en imponentes pilares cilíndricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','monumento','Núcleos de población de San Miguel de Aguayo','El término municipal incluye los siguientes núcleos de población: Santa María de Aguayo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','iglesia','Iglesia de San Miguel','Templo barroco rural del siglo XVII levantado en aparejo rústico de piedra caliza y esquinales de sillería escuadrada arenisca. Consta de una nave única rectangular con cabecera de testero plano abovedada en cañón, y una robusta espadaña de dos vanos calados para los bronces.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','monumento','Torre de los de Aguayo','Ruinas consolidadas de una estructura defensiva bajomedieval (siglo XIV) de planta cuadrangular, ejecutada en mampostería pesada y cimentaciones en opus quadratum.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39071','iglesia','Iglesia de San Pedro','Templo barroco de carácter rural (siglo XVII) edificado en mampostería basta caliza con esquinales de sillería arenisca compacta. Su nave única se cubre con bóvedas de cañón con lunetos soportadas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39071','monumento','Cabañas Pasiegas Tradicionales','Conjunto de arquitectura popular e industrial ganadera de los siglos XVIII y XIX. Estructuras exentas de gruesa mampostería de caliza calada con cubiertas a dos aguas de losas de pizarra pesada y hastiales de madera de roble machihembrada con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','monumento','Núcleos de población de San Roque de Riomiera','El término municipal incluye los siguientes núcleos de población: La Concha y Merilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','iglesia','Iglesia de San Roque','Fábrica barroca rural del siglo XVII levantada en aparejo rústico con esquinales escuadrados calizos. Cuenta con una planta rectangular que culmina en una cabecera de testero plano abovedada en cañón, albergando una pila bautismal monolítica medieval labrada a bisel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','monumento','Núcleos de población de Santa Cruz de Bezana','El término municipal incluye los siguientes núcleos de población: Mompía y Maoño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','iglesia','Iglesia de Santa Cruz de Bezana','Templo neogótico historicista edificado a principios del siglo XX sobre cimientos antiguos, combinando sillería de cantería regular en los vanos y paramentos de sillarejo calizo. Presenta una fachada principal con portalón apuntado abocinado de arquivoltas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','palacio','Palacete de los de Mompía','Residencia civil de traza ecléctica de finales del siglo XIX ejecutada en sillería arenisca compacta, con balconajes de forja artística y una galería de madera noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','monumento','Núcleos de población de Santa María de Cayón','El término municipal incluye los siguientes núcleos de población: Argomilla, Esles y La Penilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','iglesia','Iglesia de San Andrés de Argomilla','Joya del románico pleno de finales del siglo XII declarada Bien de Interés Cultural, tallada en sillería regular caliza. Destaca su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','palacio','Casonas Barrocas de Esles','Conjunto histórico homogéneo de arquitectura civil de los siglos XVII y XVIII (Casas de los de Ceballos y los de Gutiérrez). Fachadas de sillería de cantería regular arenisca con grandes portales adintelados, solanas de madera de roble con modillones y escudos de armas labrados a bisel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','monumento','Si prefieres mantener el orden alfabético estricto establecido sin desvíos geográficos o descriptivos','Si prefieres mantener el orden alfabético estricto establecido sin desvíos geográficos o descriptivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','catedral','Catedral de la Asunción de Nuestra Señora','Complejo catedralicio fortificado exento edificado entre los siglos XIII y XIV en sillería caliza compacta. Se estructura en dos plantas superpuestas, destacando la Iglesia Baja o Cripta del Cristo de estilo gótico temprano abovedada sobre robustos pilares fasciculados, y un sobrio claustro gótico con arquerías apuntadas de fina cantería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','palacio','Palacio Real de La Magdalena','Residencia palaciega exenta de rango internacional de estilo ecléctico con influencias pintoresquistas inglesas y francesas (año 1912), diseñada por Javier González de Riancho y Gonzalo Bringas. Presenta muros de mampostería de piedra arenisca de perfecta labra, sillería calada en vanos, tejados de pizarra negra apuntados, hastiales entramados vistos y amplios ventanales conopiales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','monumento','Faro de Cabo Mayor','Infraestructura civil de la ingeniería marítima del siglo XIX (año 1839) erigida en sillería de piedra arenisca regular. Consta de una esbelta torre cilíndrica de treinta metros de altura que remata en un cuerpo linterna metálico, cimentada sobre un bloque cúbico exento de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39077','monumento','Núcleos de población de Santiurde de Reinosa','El término municipal incluye los siguientes núcleos de población: Lantueno y Somballe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39077','iglesia','Iglesia de San Jorge de Lantueno','Templo gótico de carácter rural del siglo XVI levantado en aparejo regular calizo y esquinales escuadrados. Conserva un ábside de testero plano techado con una bóveda de crucería simple con arcos torales rectangulares de sección cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39077','ermita','Ermita de Santa Eulalia de Somballe','Santuario románico medieval en mampostería basta y sillería caliza arenisca en vanos, con canecillos lisos en el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','monumento','Núcleos de población de Santiurde de Toranzo','El término municipal incluye los siguientes núcleos de población: Villasevil, Acereda y Iruz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','iglesia','Iglesia de Santa Cecilia de Villasevil','Joya del románico pleno de finales del siglo XII declarada Monumento Nacional, tallada en sillería regular arenisca compacta. Destaca su monumental ábside semicircular con columnas adosadas, capiteles historiados de perfecta labra escultórica popular y un alero soportado por canecillos esculpidos con motivos zoomorfos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','iglesia','Monasterio de Nuestra Señora del Soto de Iruz','Cenobio gótico final y renacentista del siglo XVI edificado en piedra de sillería caliza. Conserva una espectacular torre herreriana campanario exenta de planta cuadrada con pilastras jónicas cajeadas y un claustro monumental con arquerías rebajadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39079','iglesia','Iglesia de Santa María del Puerto','Templo gótico tardío del siglo XIII de transición con elementos del románico tardío, edificado en sillería caliza gris de perfecta labra. Presenta una planta basilical de tres naves con bóvedas de crucería estrellada con terceletes y custodia una pila bautismal románica monolítica única sostenida por monstruos esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39079','monumento','Fuerte de San Martín y Fuerte de San Carlos','Complejo defensivo de ingeniería militar de los siglos XVII y XVIII destinado a la defensa de la bahía, tallado en sillería caliza compacta. Conserva los baluartes estrellados, fosos perimetrales, polvorines abovedados subterráneos y casamatas para piezas de artillería de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39081','monumento','Núcleos de población de Saro','El término municipal incluye los siguientes núcleos de población: Llerana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39081','iglesia','Iglesia de San Lorenzo de Llerana','Templo monumental del siglo XVII edificado en sillería arenisca compacta de regular cantería. Presenta una planta de nave única que remata en una cabecera poligonal reforzada por contrafuertes escalonados, cubierta en su tramo mayor por bóvedas de crucería estrellada con terceletes y ligaduras de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39081','palacio','Casona de los de la Sota','Residencia señorial barroca del siglo XVIII ejecutada en fábrica mixta de mampostería enlucida y esquinales escuadrados de piedra caliza, caracterizada por un portón central adintelado y un blasón de armas de fina labra heráldica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','monumento','Núcleos de población de Selaya','El término municipal incluye los siguientes núcleos de población: Pisueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','palacio','Palacio de Donadío (o de los Miera)','** Complejo palaciego barroco del siglo XVIII tallado en sillería arenisca compacta de excelente cantería. Presenta una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','iglesia','Santuario de Nuestra Señora de Valvanuz','Complejo sacro barroco del siglo XVII levantado en sillería caliza regular. Su interior consta de una nave rectangular articulada con pilastras toscanas, crucero cubierto por cúpula sobre pechinas y alberga un suntuoso retablo mayor churrigueresco de madera de nogal tallada y dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','monumento','Núcleos de población de Soba','El término municipal incluye los siguientes núcleos de población: Veguilla y Asón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','monumento','Torre de los de Velasco en Quintana','Fortaleza militar bajomedieval del siglo XV erigida en bloque cúbico exento de gruesa mampostería caliza y esquinales escuadrados de sillería fina. Presenta una planta cuadrada dotada de adarves defensivos, líneas de saeteras originales y modillones en los voladizos superiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','iglesia','Iglesia de San Miguel de Veguilla','Fábrica del siglo XVI de transición gótico-renacentista construida en cantería de sillería regular caliza. El interior destaca por sus bóvedas de crucería simple con nervios diagonales moldurados y claves labradas con relieves figurativos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39086','monumento','Conjunto Histórico de Bárcena Mayor','Conjunto urbano de rango nacional y arquitectura civil tradicional montañesa de los siglos XVII y XVIII, edificado con rigurosa consistencia en sillería arenisca de cantería regular y mampostería basta. Las viviendas se organizan en hileras exentas con plantas bajas porticadas mediante arcos de medio punto, amplias solanas superiores de madera de roble machihembrada con modillones tallados y tejados a dos aguas de gruesas losas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39086','iglesia','Iglesia de Santa María de Bárcena Mayor','Templo de origen gótico (siglo XVI) profundamente reformado en la etapa barroca, levantado en aparejo regular calizo, que alberga una nave rectangular cubierta por bóveda de crucería simple con claves lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','monumento','Núcleos de población de Torrelavega','El término municipal incluye los siguientes núcleos de población: Viérnoles y Tanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','palacio','Palacio de los Hornillos en Viérnoles (o de los Ceballos)','** Residencia señorial barroca del siglo XVIII tallada en sillería de piedra arenisca regular de excelente cantería. Presenta una fachada principal exenta estructurada en dos pisos con portón adintelado moldurado, balcones de forja artística y blasones de gran virtuosismo heráldico con volutas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','iglesia','Iglesia de la Asunción','Templo monumental de traza historicista neogótica edificado a finales del siglo XIX (año 1892) en perfecta sillería caliza compacta. Presenta una fachada de colosales proporciones con una gran portada abocinada de arquivoltas apuntadas y una esbelta torre campanario con aguja calada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','palacio','Conjunto de Casonas de Viérnoles','Unidades residenciales barrocas de los siglos XVII y XVIII (Casas de los de Villa y los de Ruiz de Villa), caracterizadas por fachadas simétricas de sillería calada y grandes blasones heráldicos de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39088','iglesia','Iglesia de San Pedro','Templo rural de alta montaña edificado a principios del siglo XX en sustitución de la antigua fábrica medieval, empleando mampostería basta caliza local y esquinales escuadrados. Conserva en su interior una pila bautismal monolítica medieval de sección circular labrada a bisel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39089','palacio','Casona de Tudanca (o de José María de Cossío)','** Obra cumbre de la arquitectura civil barroca montañesa del siglo XVIII (año 1753) de rango nacional, construida en sillería arenisca y mampostería enlucida. Presenta una fachada rectangular de gran longitud con portalón de medio punto de amplias dovelas radiales, una solana superior de madera de roble machihembrada apoyada sobre zapas labradas y dos blasones heráldicos exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39089','monumento','Conjunto Urbano de Tudanca','Núcleo urbano histórico homogéneo integrado por hileras de viviendas tradicionales de los siglos XVII y XVIII ejecutadas en cantería rústica caliza, aleros prominentes tallados y tejados a dos aguas de losas pétreas compactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','monumento','Núcleos de población de Udías','El término municipal incluye los siguientes núcleos de población: Pumalverde y Cobijón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','iglesia','Iglesia de San Nicolás de Pumalverde','Fábrica de origen gótico final (siglo XVI) con ampliaciones barrocas, levantada en fábrica mixta de mampostería y esquinales escuadrados de sillería arenisca. El interior de la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','monumento','Complejo de Minas de Udías (Infraestructuras históricas)','Vestigios de arqueología industrial minera del zinc del siglo XIX, conservando bocaminas reforzadas con arcos rebajados de mampuesto y restos de cargaderos de gravedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39093','monumento','Núcleos de población de Valdeprado del Río','El término municipal incluye los siguientes núcleos de población: Sotillo, Reocín de los Molinos y San Vitores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39093','iglesia','Iglesia de Santa María de Sotillo','Templo románico rural del siglo XII erigido en sillería regular arenisca compacta. Conserva un ábside semicircular con una saetera central abocinada flanqueada por capiteles de temática vegetal abstracta, un arco triunfal de medio punto y una serie de canecillos lisos en el alero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39093','ermita','Ermita de San Vitores','Santuario de mampostería basta y esquinales escuadrados levantado sobre un cerro rocoso, dotado de una portada de arco apuntado de dovelas sencillas y una techumbre de madera de roble con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','monumento','Núcleos de población de Valderredible','El término municipal incluye los siguientes núcleos de población: Polientes, San Martín de Elines, Arroyuelos, Campo de Ebro y Cadalso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','iglesia','Colegiata de San Martín de Elines','Obra cumbre del románico pleno del siglo XII de rango nacional, construida en sillería arenisca de perfecta labra regular. Destaca su ábside semicircular de esbeltas proporciones decorado al interior con dos pisos de arquerías ciegas sobre columnillas exentas y relieves de extraordinario virtuosismo escultórico popular; el exterior conserva canecillos historiados con un amplio bestiario y una singular torre campanario circular adosada de influencia románica bizantina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','iglesia','Iglesia Rupestre de los Santos Justo y Pastor de Arroyuelos','Joya de la arquitectura rupestre mozárabe del siglo X (etapa de repoblación), excavada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','iglesia','Iglesia Rupestre de Campo de Ebro','Templo excavado en roca arenisca compacta correspondiente al eremitismo altomedieval (siglo IX). Consta de una nave única rectangular que remata en una cabecera absidial de planta de herradura con banco corrido perimetral tallado en la propia roca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','ermita','Ermita Rupestre de la Virgen de Cadalso','Capilla rupestre paleocristiana y mozárabe excavada en talud arenisco, con una portada adintelada rústica y un interior abovedado toscamente que conserva un nicho sepulcral monolítico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39096','monumento','Núcleos de población de Vega de Liébana','El término municipal incluye los siguientes núcleos de población: La Vega, Bárago y Dobres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39096','iglesia','Iglesia de San Vicente de la Vega','Templo gótico de transición del siglo XVI edificado en regular fábrica caliza y esquinales escuadrados de arenisca. Alberga un presbiterio cubierto por bóveda de crucería estrellada con terceletes y ligaduras cuyos nervios apean en ménsulas molduradas de fina labra geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39096','palacio','Casonas y Hórreos de Dobres y Bárago','Conjunto de arquitectura popular lebaniega. Destacan las estructuras residenciales civiles barrocas del siglo XVII en piedra de sillería basta con blasones y los hórreos exentos construidos en madera de roble machihembrada apoyados sobre pies derechos cónicos pétreos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','monumento','Núcleos de población de Vega de Pas','El término municipal incluye los siguientes núcleos de población: Vega de Pas e Yera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','iglesia','Iglesia de Nuestra Señora de la Natividad','Fábrica de proporciones monumentales iniciada en el siglo XVII en estilo barroco severo clasicista, erigida en sillería arenisca compacta. Su interior consta de una nave única rectangular con capillas laterales hornacinas, cubierta por una bóveda de cañón con lunetos y una gran espadaña barroca de tres vanos en el hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','monumento','Cabañas Pasiegas de Yera','Conjunto homogéneo de arquitectura popular e industrial ganadera de montaña de los siglos XVIII y XIX. Estructuras exentas de gruesa mampostería caliza basta asentada a hueso con cubiertas a dos aguas de losas de pizarra pesada y hastiales de madera de roble con tirantes tensores vistos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','monumento','Núcleos de población de Villacarriedo','El término municipal incluye los siguientes núcleos de población: Santibáñez.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','palacio','Palacio de Soñanes','Obra cumbre del barroco civil en Cantabria y monumento de rango nacional (año 1715), edificado en perfecta sillería caliza compacta y arenisca. Presenta una fachada monumental que aglutina una exuberante profusión de columnas salomónicas exentas, pilastras corintias cajeadas, gárgolas zoomorfas y balaustradas profusamente decoradas de extraordinario virtuosismo escultórico; el interior alberga una monumental escalera imperial de doble tiro de alta especificidad constructiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','iglesia','Iglesia de San Martín de Santibáñez','Templo gótico final (siglo XVI) construido en sillería regular. Presenta una amplia nave única con cabecera poligonal reforzada por contrafuertes escalonados, techada con una intrincada bóveda de crucería estrellada con terceletes y ligaduras de perfecta labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39099','monumento','Núcleos de población de Villaescusa','El término municipal incluye los siguientes núcleos de población: Liaño y Obregón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39099','iglesia','Iglesia de San Juan Bautista de Liaño','Fábrica monumental barroca del siglo XVII levantada en sillería regular y mampuesto basta. Su interior se organiza en una nave única rectangular con pilastras toscanas que sostienen arcos torales cuadrangulares y bóvedas de arista revocadas en yesería lisa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39099','monumento','Instalaciones Mineras de Obregón','Conjunto de arqueología industrial minera vinculada a la extracción de hierro en Peña Cabarga (siglos XIX y XX), conservando los túneles y rampas de mampostería basta y las bases de los cargaderos de gravedad en opus caementicium.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','monumento','Núcleos de población de Villafufre','El término municipal incluye los siguientes núcleos de población: Rasillo y Vega de Villafufre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','palacio','Palacio de los de Morante en Rasillo','Casona señorial barroca del siglo XVIII ejecutada en sillería arenisca de perfecta labra. Presenta una fachada simétrica adintelada organizada en dos cuerpos, con un gran portalón central flanqueado por pilastras cajeadas y un escudo de armas heráldico flanqueado por volutas y angelotes de gran virtuosismo formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','iglesia','Iglesia de San Juan Evangelista','Fábrica barroca del siglo XVII levantada en aparejo de cantería y sillarejo, dotada de una robusta torre campanario de planta cuadrada adosada al hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39101','iglesia','Iglesia de Santa María','Templo de origen gótico (siglo XV) profundamente modificado en la etapa barroca, levantado en sillería caliza compacta y mampostería. Alberga una nave única rectangular con bóveda de crucería simple con arcos torales rectangulares de sección cuadrada, y posee una robusta torre campanario adosada al hastial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39101','palacio','Palacio de los de Negrete','Casona señorial barroca del siglo XVII construida en piedra arenisca de cantería regular, con un portalón central adintelado de amplias dovelas radiales y un gran blasón heráldico central de fina labra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','monumento','Núcleos de población de Voto','El término municipal incluye los siguientes núcleos de población: Bádames y Secadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','iglesia','Iglesia de San Juan Bautista de Secadura','Templo monumental iniciado en el siglo XVI en estilo góticorenacentista, edificado en sillería caliza gris de excelente cantería. El interior destaca por sus amplias bóvedas de crucería estrellada con terceletes y ligaduras cuyos nervios apean en imponentes pilares cilíndricos, complementado por un retablo mayor manierista de perfecta labra anatómica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','palacio','Casa-Palacio de los de Cerecedo en Bádames','Residencia señorial barroca del siglo XVII con fachada de sillería calada, portales adintelados moldurados, solanas superiores de madera de roble con modillones y grandes escudos de armas familiares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','monumento','Dar por finalizada y validada de manera definitiva esta sesión de patrimonio histórico-artístico de España','Dar por finalizada y validada de manera definitiva esta sesión de patrimonio histórico-artístico de España','inventario_monumentos_pdf');
